INSERT INTO `notes` (`id`, `user_id`, `category_id`, `title`, `description`, `subject`, `content`, `filename`, `original_name`, `filesize`, `filetype`, `downloads`, `created_at`) VALUES
(220, 1, 1, 'Calculus — Complete Notes', 'Limits, derivatives, integrals with examples', 'Mathematics', 'CALCULUS - COMPLETE NOTES\r\n\r\n1. LIMITS\r\nlim(x→a) f(x) = L\r\nKey Laws:\r\n  lim [f+g] = lim f + lim g\r\n  lim [f·g] = lim f · lim g\r\n\r\nStandard:\r\n  lim(x→0) sin(x)/x = 1\r\n  lim(x→0) (1-cos x)/x = 0\r\n  lim(x→0) (e^x - 1)/x = 1\r\n  lim(x→∞) (1 + 1/x)^x = e\r\n\r\n2. DERIVATIVES\r\nf\'(x) = lim(h→0) [f(x+h)-f(x)]/h\r\n\r\nPower: d/dx(x^n) = n·x^(n-1)\r\nProduct: (uv)\' = u\'v + uv\'\r\nChain: dy/dx = dy/du · du/dx\r\n\r\nd/dx(sin x) = cos x\r\nd/dx(cos x) = -sin x\r\nd/dx(e^x) = e^x\r\nd/dx(ln x) = 1/x\r\n\r\n3. INTEGRALS\r\n∫x^n dx = x^(n+1)/(n+1) + C\r\n∫1/x dx = ln|x| + C\r\n∫e^x dx = e^x + C\r\n∫sin x dx = -cos x + C\r\n∫cos x dx = sin x + C\r\n\r\n4. FTC\r\n∫[a,b] f(x) dx = F(b) - F(a)\r\n\r\n5. SERIES\r\ne^x = 1 + x + x²/2! + x³/3! + ...\r\nsin x = x - x³/3! + x⁵/5! - ...', 'note_220_calculus_complete_notes.pdf', 'Calculus.pdf', 1420, 'application/pdf', 342, '2026-10-08 11:16:42'),
(221, 1, 1, 'Linear Algebra — Master Guide', 'Matrices, determinants, eigenvalues', 'Mathematics', 'LINEAR ALGEBRA\r\n\r\n1. MATRICES\r\n(AB)C = A(BC)\r\nA(B+C) = AB + AC\r\nAB ≠ BA\r\n(AB)^T = B^T A^T\r\n(AB)^-1 = B^-1 A^-1\r\n\r\n2. DETERMINANTS\r\n2×2: ad-bc\r\ndet(AB) = det(A)det(B)\r\ndet(A^T) = det(A)\r\ndet(A^-1) = 1/det(A)\r\n\r\n3. EIGENVALUES\r\nAv = λv, v≠0\r\ndet(A - λI) = 0\r\nSum λ = trace(A)\r\nProduct λ = det(A)\r\n\r\n4. DIAGONALIZATION\r\nA = PDP^-1\r\nA^n = PD^n P^-1\r\n\r\n5. SVD\r\nA = UΣV^T\r\nMost important factorization', 'note_221_linear_algebra_master_guide.pdf', 'LinearAlgebra.pdf', 1175, 'application/pdf', 287, '2026-10-08 11:16:42'),
(222, 1, 1, 'Trigonometry Cheat Sheet', 'All identities and formulas', 'Mathematics', 'TRIGONOMETRY\r\n\r\nsin²x + cos²x = 1\r\n1 + tan²x = sec²x\r\n1 + cot²x = csc²x\r\n\r\nsin(A+B) = sinA cosB + cosA sinB\r\ncos(A+B) = cosA cosB - sinA sinB\r\ntan(A+B) = (tanA+tanB)/(1-tanA tanB)\r\n\r\nsin(2A) = 2 sinA cosA\r\ncos(2A) = cos²A - sin²A\r\n\r\nStandard Values:\r\nθ    |  0  | 30  | 45  | 60  | 90\r\nsin  |  0  | 1/2 |1/√2 |√3/2 |  1\r\ncos  |  1  |√3/2 |1/√2 | 1/2 |  0\r\n\r\nLaw of Sines: a/sinA = b/sinB = c/sinC\r\nLaw of Cosines: c² = a²+b²-2ab·cosC', 'note_222_trigonometry_cheat_sheet.pdf', 'Trig.pdf', 1144, 'application/pdf', 456, '2026-10-08 11:16:42'),
(223, 1, 1, 'Probability & Statistics', 'Probability rules, distributions, tests', 'Mathematics', 'PROBABILITY & STATISTICS\r\n\r\n1. PROBABILITY\r\nP(A) = favorable/total\r\nP(A\') = 1 - P(A)\r\nP(A∪B) = P(A) + P(B) - P(A∩B)\r\nP(A|B) = P(A∩B)/P(B)\r\nBayes: P(A|B) = P(B|A)P(A)/P(B)\r\n\r\n2. RANDOM VARIABLES\r\nE(X) = Σ x·P(X=x)\r\nVar(X) = E(X²) - [E(X)]²\r\n\r\n3. DISTRIBUTIONS\r\nBinomial: C(n,k)p^k(1-p)^(n-k)\r\nMean=np, Var=np(1-p)\r\n\r\nPoisson: e^-λ λ^k/k!, Mean=Var=λ\r\n\r\nNormal: 68-95-99.7 rule\r\n\r\n4. HYPOTHESIS\r\nZ-test: (x̄-μ)/(σ/√n)\r\nT-test: (x̄-μ)/(s/√n)\r\nα=0.05 → reject if p<α\r\n\r\n5. REGRESSION\r\ny = a + bx\r\nr ∈ [-1, 1]', 'note_223_probability_statistics.pdf', 'Stats.pdf', 1182, 'application/pdf', 198, '2026-10-08 11:16:42'),
(224, 1, 1, 'Differential Equations', 'ODEs, PDEs, Laplace transforms', 'Mathematics', 'DIFFERENTIAL EQUATIONS\r\n\r\n1. FIRST ORDER\r\nSeparable: dy/dx = f(x)g(y)\r\nLinear: dy/dx + P(x)y = Q(x)\r\nIntegrating factor: e^∫P dx\r\n\r\n2. SECOND ORDER\r\nay\' + by\' + cy = 0\r\nCharacteristic: ar² + br + c = 0\r\n\r\nCases:\r\n  r₁ ≠ r₂: y = C₁e^r₁x + C₂e^r₂x\r\n  r₁ = r₂: y = (C₁+C₂x)e^rx\r\n  Complex: y = e^αx(C₁cos βx + C₂sin βx)\r\n\r\n3. LAPLACE TRANSFORM\r\nL{f(t)} = ∫[0,∞] e^-st f(t) dt\r\nL{1} = 1/s\r\nL{e^at} = 1/(s-a)\r\nL{sin at} = a/(s²+a²)\r\nL{cos at} = s/(s²+a²)\r\n\r\n4. APPLICATIONS\r\n  • Population growth\r\n  • Spring-mass\r\n  • RC/RL circuits\r\n  • Heat equation', 'note_224_differential_equations.pdf', 'DiffEq.pdf', 1216, 'application/pdf', 156, '2026-10-08 11:16:42'),
(225, 1, 1, 'Discrete Mathematics', 'Logic, sets, graphs, combinatorics', 'Mathematics', 'DISCRETE MATHEMATICS\r\n\r\n1. LOGIC\r\nAND: p ∧ q\r\nOR: p ∨ q\r\nNOT: ¬p\r\nImplication: p → q\r\nBiconditional: p ↔ q\r\n\r\nTruth tables, De Morgan\'s laws\r\n¬(p∧q) = ¬p ∨ ¬q\r\n¬(p∨q) = ¬p ∧ ¬q\r\n\r\n2. SETS\r\nUnion: A∪B\r\nIntersection: A∩B\r\nDifference: A-B\r\nComplement: A\'\r\n\r\n3. RELATIONS\r\nReflexive: aRa\r\nSymmetric: aRb ⟹ bRa\r\nTransitive: aRb, bRc ⟹ aRc\r\nEquivalence: all three\r\n\r\n4. COMBINATORICS\r\nP(n,r) = n!/(n-r)!\r\nC(n,r) = n!/(r!(n-r)!)\r\nPigeonhole principle\r\n\r\n5. GRAPH THEORY\r\nVertices V, Edges E\r\nDegree sum = 2|E|\r\nEuler: all even degrees\r\nHamiltonian: visits all once\r\n\r\n6. RECURRENCE\r\nT(n) = 2T(n/2) + n\r\nMaster theorem', 'note_225_discrete_mathematics.pdf', 'Discrete.pdf', 1353, 'application/pdf', 234, '2026-10-08 11:16:42'),
(226, 1, 1, 'Number Theory', 'Primes, GCD, modular arithmetic', 'Mathematics', 'NUMBER THEORY\r\n\r\n1. DIVISIBILITY\r\na|b if b = ak\r\nEuclidean: gcd(a,b) = gcd(b, a mod b)\r\n\r\n2. PRIMES\r\nPrime: only 1 and itself\r\nFundamental theorem:\r\nEvery n > 1 = unique product of primes\r\n\r\n3. MODULAR ARITHMETIC\r\na ≡ b (mod n)\r\nFermat: a^(p-1) ≡ 1 (mod p)\r\nEuler: a^φ(n) ≡ 1 (mod n)\r\nCRT: solve system of congruences\r\n\r\n4. RSA\r\nn = p·q\r\nφ(n) = (p-1)(q-1)\r\ne·d ≡ 1 (mod φ(n))\r\n\r\n5. FUNCTIONS\r\nφ(n): count coprime to n\r\nτ(n): number of divisors\r\nσ(n): sum of divisors', 'note_226_number_theory.pdf', 'NumberTheory.pdf', 1104, 'application/pdf', 145, '2026-10-08 11:16:42'),
(227, 1, 1, 'Real Analysis', 'Sequences, series, continuity, limits', 'Mathematics', 'REAL ANALYSIS\r\n\r\n1. SEQUENCES\r\nConvergent: lim aₙ = L\r\nCauchy: |aₘ-aₙ| < ε\r\n\r\n2. SERIES\r\nΣaₙ converges\r\nTests:\r\n  Ratio: lim|aₙ₊₁/aₙ| < 1\r\n  Root: lim|aₙ|^(1/n) < 1\r\n  Comparison\r\n  Integral\r\n\r\n3. CONTINUITY\r\nf continuous at c if lim f(x) = f(c)\r\nε-δ definition\r\n\r\n4. DIFFERENTIATION\r\nMean Value Theorem\r\nRolle\'s Theorem\r\nTaylor\'s Theorem\r\n\r\n5. RIEMANN INTEGRAL\r\nPartitions, upper/lower sums\r\nIntegrable if limits equal\r\n\r\n6. METRIC SPACES\r\nd(x,y) ≥ 0\r\nd(x,y) = 0 ⟺ x = y\r\nd(x,y) = d(y,x)\r\nd(x,z) ≤ d(x,y) + d(y,z)', 'note_227_real_analysis.pdf', 'RealAnalysis.pdf', 1214, 'application/pdf', 123, '2026-10-08 11:16:42'),
(228, 1, 1, 'Complex Analysis', 'Complex numbers, analytic functions', 'Mathematics', 'COMPLEX ANALYSIS\r\n\r\n1. COMPLEX NUMBERS\r\nz = a + bi\r\n|z| = √(a²+b²)\r\nz̄ = a - bi\r\n\r\n2. EULER\'S FORMULA\r\ne^(iθ) = cos θ + i sin θ\r\ne^(iπ) + 1 = 0\r\n\r\n3. ANALYTIC FUNCTIONS\r\nCauchy-Riemann:\r\n  ∂u/∂x = ∂v/∂y\r\n  ∂u/∂y = -∂v/∂x\r\n\r\n4. CAUCHY INTEGRAL\r\n∮ f(z)/(z-a) dz = 2πi·f(a)\r\n\r\n5. RESIDUE THEOREM\r\n∮ f(z) dz = 2πi·Σ Residues\r\n\r\n6. CONTOUR INTEGRATION\r\nReal integrals via complex\r\nJordan\'s lemma', 'note_228_complex_analysis.pdf', 'Complex.pdf', 1047, 'application/pdf', 98, '2026-10-08 11:16:42'),
(229, 1, 1, 'Numerical Methods', 'Roots, interpolation, integration', 'Mathematics', 'NUMERICAL METHODS\r\n\r\n1. ROOT FINDING\r\nBisection: halve interval\r\nNewton-Raphson: xₙ₊₁ = xₙ - f(xₙ)/f\'(xₙ)\r\nSecant method\r\nFixed point: x = g(x)\r\n\r\n2. INTERPOLATION\r\nLagrange polynomial\r\nNewton divided differences\r\nCubic splines\r\n\r\n3. NUMERICAL INTEGRATION\r\nTrapezoidal rule\r\nSimpson\'s 1/3 rule\r\nSimpson\'s 3/8 rule\r\nGauss quadrature\r\n\r\n4. ODE SOLVERS\r\nEuler method\r\nRunge-Kutta (RK4)\r\nAdams-Bashforth\r\n\r\n5. LINEAR SYSTEMS\r\nGaussian elimination\r\nLU decomposition\r\nJacobi iteration\r\nGauss-Seidel', 'note_229_numerical_methods.pdf', 'Numerical.pdf', 1273, 'application/pdf', 167, '2026-10-08 11:16:42'),
(230, 1, 2, 'Classical Mechanics', 'Kinematics, Newton laws, energy', 'Physics', 'CLASSICAL MECHANICS\r\n\r\n1. KINEMATICS\r\nv = u + at\r\ns = ut + ½at²\r\nv² = u² + 2as\r\n\r\nProjectile:\r\n  T = 2u sinθ/g\r\n  R = u²sin2θ/g\r\n  H = u²sin²θ/(2g)\r\n\r\n2. NEWTON\r\nF = ma = dp/dt\r\nAction = Reaction\r\n\r\n3. FRICTION\r\nf_s ≤ μ_s N\r\nf_k = μ_k N\r\n\r\n4. ENERGY\r\nKE = ½mv²\r\nPE = mgh\r\nSpring: ½kx²\r\nW = Fd cosθ\r\nWork-Energy: W = ΔKE\r\n\r\n5. MOMENTUM\r\np = mv\r\nJ = FΔt = Δp\r\nElastic: KE conserved\r\nInelastic: KE lost\r\n\r\n6. ROTATION\r\nω = dθ/dt\r\nτ = Iα\r\nL = Iω\r\nI_rod = (1/12)mL²\r\nI_sphere = (2/5)mR²\r\n\r\n7. GRAVITATION\r\nF = Gm₁m₂/r²\r\ng = GM/r²\r\nv_esc = √(2GM/R) = 11.2 km/s\r\n\r\n8. SHM\r\nF = -kx\r\nx = A cos(ωt+φ)\r\nT = 2π√(m/k)', 'note_230_classical_mechanics.pdf', 'Mechanics.pdf', 1539, 'application/pdf', 234, '2026-10-08 11:16:42'),
(231, 1, 2, 'Thermodynamics', 'Laws, engines, entropy, kinetic theory', 'Physics', 'THERMODYNAMICS\r\n\r\n1. FIRST LAW\r\nΔU = Q - W\r\n\r\nProcesses:\r\n  Isobaric: W = PΔV\r\n  Isothermal: W = nRT ln(V₂/V₁)\r\n  Isochoric: W = 0\r\n  Adiabatic: W = -ΔU\r\n\r\n2. HEAT\r\nQ = mcΔT = nCΔT\r\nCp - Cv = R\r\nγ = Cp/Cv\r\n\r\n3. SECOND LAW\r\nΔS ≥ ∫dQ/T\r\nKelvin-Planck, Clausius\r\n\r\n4. CARNOT\r\nη = 1 - T_C/T_H\r\n\r\n5. KINETIC THEORY\r\nPV = nRT\r\nv_rms = √(3kT/m)\r\nKE_avg = (3/2)kT\r\n\r\n6. HEAT TRANSFER\r\nConduction: Q/t = kAΔT/L\r\nConvection: Q/t = hAΔT\r\nRadiation: P = eσAT⁴\r\n\r\nWien: λ_max = 2.898×10⁻³/T\r\n\r\n7. PHASE CHANGES\r\nQ = mL\r\nWater: L_f = 334 kJ/kg\r\nL_v = 2260 kJ/kg', 'note_231_thermodynamics.pdf', 'Thermo.pdf', 1149, 'application/pdf', 189, '2026-10-08 11:16:42'),
(232, 1, 2, 'Quantum Physics', 'Wave-particle, Bohr, Schrödinger', 'Physics', 'QUANTUM PHYSICS\r\n\r\n1. DE BROGLIE\r\nλ = h/p = h/(mv)\r\nh = 6.626×10⁻³⁴ J·s\r\n\r\n2. PHOTOELECTRIC\r\nKE_max = hf - φ\r\nφ = work function\r\nThreshold: f₀ = φ/h\r\n\r\n3. BOHR MODEL\r\nE_n = -13.6/n² eV\r\nr_n = n²·a₀ = n²·0.529 Å\r\n\r\nSeries:\r\n  Lyman: n→1 (UV)\r\n  Balmer: n→2 (Visible)\r\n  Paschen: n→3 (IR)\r\n\r\nRydberg: 1/λ = R(1/n₁²-1/n₂²)\r\n\r\n4. SCHRÖDINGER\r\n-(ℏ²/2m)∇²ψ + Vψ = Eψ\r\n|ψ|² = probability density\r\nParticle in box: E_n = n²h²/(8mL²)\r\n\r\n5. HEISENBERG\r\nΔx·Δp ≥ ℏ/2\r\nΔE·Δt ≥ ℏ/2\r\n\r\n6. TUNNELING\r\nT ≈ e^(-2κL)\r\n\r\n7. ATOMIC\r\nPauli, Aufbau, Hund\r\n1s 2s 2p 3s 3p 4s 3d 4p...', 'note_232_quantum_physics.pdf', 'Quantum.pdf', 1178, 'application/pdf', 312, '2026-10-08 11:16:42'),
(233, 1, 2, 'Electromagnetism', 'E-fields, B-fields, Maxwell', 'Physics', 'ELECTROMAGNETISM\r\n\r\n1. ELECTROSTATICS\r\nF = kq₁q₂/r²\r\nk = 9×10⁹\r\nE = kQ/r²\r\nV = kQ/r\r\n\r\n2. GAUSS\r\nΦ = Q_enc/ε₀\r\nε₀ = 8.85×10⁻¹²\r\n\r\nLine: E = λ/(2πε₀r)\r\nSheet: E = σ/(2ε₀)\r\n\r\n3. CAPACITORS\r\nC = Q/V\r\nParallel: C = ε₀A/d\r\nU = ½CV²\r\nSeries: 1/C = 1/C₁+1/C₂\r\nParallel: C = C₁+C₂\r\n\r\n4. CIRCUITS\r\nOhm: V = IR\r\nP = VI = I²R = V²/R\r\nSeries R = R₁+R₂\r\nParallel 1/R = 1/R₁+1/R₂\r\n\r\nKirchhoff\'s laws\r\n\r\n5. MAGNETISM\r\nF = qvB sinθ\r\nF = ILB sinθ\r\nBiot-Savart\r\nAmpere\'s law\r\n\r\nWire: B = μ₀I/(2πr)\r\nSolenoid: B = μ₀nI\r\n\r\n6. INDUCTION\r\nFaraday: EMF = -N dΦ/dt\r\nLenz\'s law\r\nMotional: EMF = BLv\r\n\r\n7. MAXWELL\r\n4 equations\r\n\r\n8. EM WAVES\r\nc = 3×10⁸ m/s\r\nc = E/B\r\nSpectrum: Radio, Micro, IR, Visible, UV, X, Gamma', 'note_233_electromagnetism.pdf', 'EM.pdf', 1543, 'application/pdf', 267, '2026-10-08 11:16:42'),
(234, 1, 2, 'Modern Physics', 'Relativity, atomic, nuclear', 'Physics', 'MODERN PHYSICS\r\n\r\n1. SPECIAL RELATIVITY\r\nγ = 1/√(1-v²/c²)\r\nTime dilation: Δt = γΔt₀\r\nLength: L = L₀/γ\r\nE = mc²\r\nE² = (pc)² + (mc²)²\r\n\r\n2. ATOMIC STRUCTURE\r\nRutherford, Bohr models\r\nQuantum numbers:\r\n  n (principal)\r\n  l (angular)\r\n  m_l (magnetic)\r\n  m_s (spin)\r\n\r\n3. NUCLEAR\r\nNucleus = protons + neutrons\r\nZ = protons\r\nA = Z + N\r\nBinding energy: BE = Δm·c²\r\nMass defect\r\n\r\nDecays:\r\n  α: Z-2, A-4\r\n  β⁻: Z+1\r\n  β⁺: Z-1\r\n  γ: no change\r\n\r\nHalf-life:\r\nN = N₀(1/2)^(t/t_half)\r\n\r\n4. FISSION\r\nHeavy → lighter + energy\r\nU-235 + n → Ba + Kr + 3n\r\n\r\n5. FUSION\r\nLight → heavier\r\n4H → He + energy\r\nStars, hydrogen bomb', 'note_234_modern_physics.pdf', 'Modern.pdf', 1313, 'application/pdf', 245, '2026-10-08 11:16:42'),
(235, 1, 2, 'Optics', 'Reflection, refraction, interference', 'Physics', 'OPTICS\r\n\r\n1. REFLECTION\r\nAngle i = angle r\r\nPlane mirror\r\nSpherical mirrors\r\nMirror formula: 1/f = 1/v + 1/u\r\nMagnification: m = -v/u\r\n\r\n2. REFRACTION\r\nSnell: n₁ sin θ₁ = n₂ sin θ₂\r\nRefractive index: n = c/v\r\nCritical angle: sin θ_c = n₂/n₁\r\nTotal internal reflection\r\n\r\n3. LENSES\r\n1/f = 1/v - 1/u\r\nm = v/u\r\nPower: P = 1/f (diopters)\r\n\r\n4. WAVE OPTICS\r\nInterference:\r\n  Young\'s double slit\r\n  Path difference: Δx = d sin θ\r\n  Maxima: Δx = nλ\r\n  Minima: Δx = (n+½)λ\r\n\r\nDiffraction:\r\n  Single slit: a sin θ = nλ\r\n  Grating: d sin θ = nλ\r\n\r\n5. POLARIZATION\r\nMalus: I = I₀ cos²θ\r\nBrewster: tan θ_p = n₂/n₁\r\n\r\n6. DISPERSION\r\nPrism, rainbow\r\nViolet bends most', 'note_235_optics.pdf', 'Optics.pdf', 1260, 'application/pdf', 178, '2026-10-08 11:16:42'),
(236, 1, 2, 'Waves & Sound', 'Wave motion, interference, Doppler', 'Physics', 'WAVES & SOUND\r\n\r\n1. WAVE EQUATION\r\ny = A sin(kx - ωt)\r\nk = 2π/λ\r\nω = 2πf\r\nv = fλ = ω/k\r\n\r\n2. TYPES\r\nTransverse (light)\r\nLongitudinal (sound)\r\nStanding waves\r\n\r\n3. SUPERPOSITION\r\nConstructive: Δ = nλ\r\nDestructive: Δ = (n+½)λ\r\n\r\n4. BEATS\r\nf_beat = |f₁ - f₂|\r\n\r\n5. DOPPLER\r\nf\' = f(v ± v_o)/(v ∓ v_s)\r\n\r\n6. SOUND\r\nSpeed in air ~ 343 m/s\r\nSpeed in water ~ 1500 m/s\r\n\r\nIntensity: I = P/(4πr²)\r\ndB = 10 log(I/I₀)\r\n\r\n7. STANDING WAVES\r\nString: f_n = nv/(2L)\r\nOpen pipe: f_n = nv/(2L)\r\nClosed pipe: f_n = (2n-1)v/(4L)\r\n\r\n8. RESONANCE\r\nNatural frequency', 'note_236_waves_sound.pdf', 'Waves.pdf', 1217, 'application/pdf', 145, '2026-10-08 11:16:42'),
(237, 1, 2, 'Fluid Mechanics', 'Pressure, buoyancy, Bernoulli', 'Physics', 'FLUID MECHANICS\r\n\r\n1. PRESSURE\r\nP = F/A\r\nPascal: 1 Pa = 1 N/m²\r\n\r\nHydrostatic: P = P₀ + ρgh\r\n\r\n2. PASCAL\'S LAW\r\nPressure transmitted equally\r\nHydraulic lift\r\n\r\n3. ARCHIMEDES\r\nF_B = ρ_fluid · V_displaced · g\r\nFloat if ρ_obj < ρ_fluid\r\nSink if ρ_obj > ρ_fluid\r\n\r\n4. CONTINUITY\r\nA₁v₁ = A₂v₂\r\n\r\n5. BERNOULLI\r\nP + ½ρv² + ρgh = const\r\n\r\nApplications:\r\n  Airplane wings\r\n  Venturi meter\r\n  Pitot tube\r\n  Atomizer\r\n\r\n6. VISCOSITY\r\nF = ηA(dv/dx)\r\nPoiseuille: Q = πr⁴ΔP/(8ηL)\r\nStokes: F = 6πηrv\r\n\r\nReynolds: Re = ρvD/η\r\nRe < 2000: laminar\r\nRe > 4000: turbulent\r\n\r\n7. SURFACE TENSION\r\nγ = F/L\r\nCapillary rise: h = 2γcosθ/(ρgr)', 'note_237_fluid_mechanics.pdf', 'Fluids.pdf', 1202, 'application/pdf', 134, '2026-10-08 11:16:42'),
(238, 1, 3, 'Data Structures', 'Arrays, linked lists, trees, graphs', 'Computer Science', 'DATA STRUCTURES\r\n\r\n1. ARRAYS\r\nAccess O(1), Search O(n)\r\nFixed size, contiguous\r\n\r\n2. LINKED LISTS\r\nSingly, Doubly, Circular\r\nAccess O(n), Insert head O(1)\r\n\r\n3. STACKS (LIFO)\r\npush, pop, peek O(1)\r\nApps: Function calls, Undo, DFS\r\n\r\n4. QUEUES (FIFO)\r\nenqueue, dequeue O(1)\r\nCircular, Priority, Deque\r\nApps: BFS, Scheduling\r\n\r\n5. TREES\r\nBinary, BST, AVL, Red-Black\r\nTraversals:\r\n  Inorder: L-Root-R\r\n  Preorder: Root-L-R\r\n  Postorder: L-R-Root\r\nBST: O(log n) avg\r\n\r\n6. HEAPS\r\nMax/Min\r\nInsert O(log n)\r\nExtract O(log n)\r\nPeek O(1)\r\n\r\n7. GRAPHS\r\nMatrix O(V²), List O(V+E)\r\nBFS, DFS O(V+E)\r\n\r\n8. HASH TABLES\r\nO(1) average\r\nChaining, Open addressing\r\nLoad factor n/m\r\n\r\n9. SORTING\r\nBubble O(n²)\r\nSelection O(n²)\r\nInsertion O(n²)\r\nMerge O(nlogn)\r\nQuick O(nlogn) avg\r\nHeap O(nlogn)', 'note_238_data_structures.pdf', 'DS.pdf', 1951, 'application/pdf', 892, '2026-10-08 11:16:42'),
(239, 1, 3, 'Algorithms', 'D&C, greedy, DP, NP', 'Computer Science', 'ALGORITHMS\r\n\r\n1. COMPLEXITY\r\nO(1) < O(log n) < O(n) < O(n log n) < O(n²) < O(2^n)\r\n\r\n2. MASTER THEOREM\r\nT(n) = aT(n/b) + f(n)\r\n3 cases based on n^(log_b a)\r\n\r\n3. DIVIDE & CONQUER\r\nMerge Sort O(nlogn)\r\nQuick Sort O(nlogn)\r\nBinary Search O(logn)\r\nStrassen O(n^2.81)\r\n\r\n4. GREEDY\r\nActivity Selection\r\nHuffman Coding\r\nDijkstra, Prim, Kruskal\r\nFractional Knapsack\r\n\r\n5. DYNAMIC PROGRAMMING\r\nFibonacci O(n)\r\n0/1 Knapsack O(nW)\r\nLCS O(mn)\r\nEdit Distance O(mn)\r\nMatrix Chain O(n³)\r\nCoin Change\r\n\r\n6. GRAPH\r\nBFS O(V+E)\r\nDFS O(V+E)\r\nDijkstra O((V+E)logV)\r\nBellman-Ford O(VE)\r\nFloyd-Warshall O(V³)\r\nTopological O(V+E)\r\n\r\n7. NP-COMPLETENESS\r\nP, NP, NP-Complete, NP-Hard\r\nSAT, 3-SAT, Clique, TSP\r\nReduction: A ≤ₚ B\r\n\r\n8. APPROXIMATION\r\nTSP: 2-approx\r\nVertex Cover: 2-approx\r\nSet Cover: O(log n)', 'note_239_algorithms.pdf', 'Algo.pdf', 1943, 'application/pdf', 567, '2026-10-08 11:16:42'),
(240, 1, 3, 'DBMS', 'SQL, normalization, transactions', 'Computer Science', 'DBMS\r\n\r\n1. ER MODEL\r\nEntity, Attribute, Relationship\r\n1:1, 1:N, M:N\r\nSuper, Candidate, Primary, Foreign keys\r\n\r\n2. NORMALIZATION\r\n1NF: atomic\r\n2NF: 1NF + no partial dep\r\n3NF: 2NF + no transitive dep\r\nBCNF: every determinant is CK\r\n\r\n3. SQL\r\nDDL: CREATE, ALTER, DROP\r\nDML: INSERT, UPDATE, DELETE\r\nDQL: SELECT\r\n\r\nSELECT col FROM t\r\nWHERE cond\r\nGROUP BY col\r\nHAVING cond\r\nORDER BY col;\r\n\r\nJoins: INNER, LEFT, RIGHT, FULL\r\n\r\n4. ACID\r\nAtomicity, Consistency, Isolation, Durability\r\n\r\n5. ISOLATION LEVELS\r\nRead Uncommitted → Serializable\r\n\r\n6. LOCKING\r\nShared, Exclusive\r\n2PL, Deadlock detection\r\n\r\n7. INDEXING\r\nB-Tree, B+ Tree, Hash, Bitmap\r\nClustered vs Non-clustered\r\n\r\n8. QUERY OPT\r\nHeuristic, Cost-based\r\nEXPLAIN', 'note_240_dbms.pdf', 'DBMS.pdf', 1821, 'application/pdf', 445, '2026-10-08 11:16:42'),
(241, 1, 3, 'Operating Systems', 'Processes, memory, files', 'Computer Science', 'OPERATING SYSTEMS\r\n\r\n1. PROCESSES\r\nNew, Ready, Running, Waiting, Terminated\r\nPCB: PID, PC, registers\r\nProcess vs Thread\r\n\r\n2. SCHEDULING\r\nFCFS: convoy\r\nSJF: optimal\r\nSRTF: preemptive\r\nRR: quantum\r\nPriority: aging\r\nMLFQ\r\n\r\n3. SYNCHRONIZATION\r\nCritical section\r\nMutual exclusion\r\nPeterson\'s, Test-and-Set\r\nSemaphore, Mutex, Monitor\r\nProducer-Consumer, Dining Philosophers\r\n\r\n4. DEADLOCK\r\n4 conditions\r\nPrevention, Avoidance, Detection, Recovery\r\nBanker\'s algorithm\r\n\r\n5. MEMORY\r\nPaging, Segmentation, Virtual\r\nPage replacement: FIFO, LRU, Optimal, Clock\r\nThrashing\r\n\r\n6. FILE SYSTEMS\r\nContiguous, Linked, Indexed\r\nB-Tree directories\r\nPermissions\r\n\r\n7. I/O\r\nProgrammed, Interrupt, DMA\r\nDisk scheduling: FCFS, SSTF, SCAN\r\nRAID levels', 'note_241_operating_systems.pdf', 'OS.pdf', 1588, 'application/pdf', 378, '2026-10-08 11:16:42'),
(242, 1, 3, 'Machine Learning', 'Supervised, unsupervised, NN', 'Computer Science', 'MACHINE LEARNING\r\n\r\n1. TYPES\r\nSupervised, Unsupervised, Reinforcement, Semi\r\n\r\n2. SUPERVISED\r\nLinear Regression:\r\n  y = w₀ + w₁x₁ + ...\r\n  MSE = (1/n)Σ(y_pred - y_true)²\r\n  Gradient descent\r\n\r\nLogistic: sigmoid(z) = 1/(1+e^-z)\r\nDecision Trees: Gini, Entropy\r\nRandom Forest: ensemble\r\nSVM: max-margin, kernels\r\nKNN: lazy, majority\r\nNaive Bayes: independence\r\n\r\n3. UNSUPERVISED\r\nK-Means: centroid iteration\r\nHierarchical: dendrogram\r\nDBSCAN: density\r\nPCA: eigenvectors\r\n\r\n4. NEURAL NETWORKS\r\nPerceptron\r\nActivations: Sigmoid, Tanh, ReLU, Softmax\r\nBackprop\r\nOptimizers: SGD, Adam\r\nRegularization: L1, L2, Dropout\r\n\r\n5. DEEP LEARNING\r\nCNN: images\r\nRNN: sequences\r\nLSTM: long deps\r\nTransformer: attention\r\n\r\n6. EVALUATION\r\nAccuracy, Precision, Recall, F1\r\nMSE, RMSE, MAE, R²\r\nCross-validation\r\n\r\n7. FEATURES\r\nNormalization, Standardization\r\nOne-hot, Polynomial\r\nSMOTE', 'note_242_machine_learning.pdf', 'ML.pdf', 1942, 'application/pdf', 623, '2026-10-08 11:16:42'),
(243, 1, 3, 'Python Programming', 'Python basics to advanced', 'Computer Science', 'PYTHON PROGRAMMING\r\n\r\n1. BASICS\r\nVariables: no type declaration\r\nprint(\"Hello\")\r\ninput() for reading\r\n\r\n2. DATA TYPES\r\nint, float, str, bool\r\nlist, tuple, set, dict\r\ntype(x), isinstance(x, int)\r\n\r\n3. STRINGS\r\ns.upper(), s.lower()\r\ns.split(), s.strip()\r\ns.replace()\r\nf-strings: f\"Hi {name}\"\r\n\r\n4. CONTROL\r\nif/elif/else\r\nfor x in range(5)\r\nwhile cond\r\n\r\n5. FUNCTIONS\r\ndef f(a, b=0): return a+b\r\n*args, **kwargs\r\nlambda x: x**2\r\n\r\n6. LISTS\r\nappend, insert, remove, pop\r\nsort, reverse\r\nSlicing: [1:3], [::-1]\r\nComprehensions: [x**2 for x in range(10)]\r\n\r\n7. DICTS\r\nperson = {\"name\": \"John\"}\r\nperson[\"age\"] = 25\r\n.get(key, default)\r\n\r\n8. OOP\r\nclass Animal:\r\n  def __init__(self, name):\r\n    self.name = name\r\n  def speak(self):\r\n    return \"...\"\r\nclass Dog(Animal):\r\n  def speak(self):\r\n    return \"Woof\"\r\n\r\n9. FILE I/O\r\nwith open(\"f.txt\", \"r\") as f:\r\n  content = f.read()\r\n\r\n10. ERROR HANDLING\r\ntry/except/finally\r\nValueError, ZeroDivisionError\r\n\r\n11. LIBRARIES\r\nrequests, numpy, pandas\r\nmatplotlib, flask, django', 'note_243_python_programming.pdf', 'Python.pdf', 2202, 'application/pdf', 756, '2026-10-08 11:16:42'),
(244, 1, 3, 'Java Programming', 'Java OOP, collections', 'Computer Science', 'JAVA PROGRAMMING\r\n\r\n1. BASICS\r\npublic class Main {\r\n  public static void main(String[] args) {\r\n    System.out.println(\"Hello\");\r\n  }\r\n}\r\n\r\n2. TYPES\r\nint, double, boolean, char\r\nString, arrays\r\nWrapper: Integer, Double\r\n\r\n3. OOP\r\nclass, object\r\nInheritance: extends\r\nPolymorphism: override\r\nEncapsulation: private + getters/setters\r\nAbstraction: abstract class, interface\r\n\r\n4. COLLECTIONS\r\nList: ArrayList, LinkedList\r\nSet: HashSet, TreeSet\r\nMap: HashMap, TreeMap\r\nIterator\r\n\r\n5. EXCEPTIONS\r\ntry/catch/finally\r\nChecked: IOException\r\nUnchecked: NullPointerException\r\nthrow, throws\r\n\r\n6. GENERICS\r\nList<String> names\r\nclass Box<T>\r\n\r\n7. STREAMS\r\nlist.stream()\r\n  .filter(x -> x > 5)\r\n  .map(x -> x * 2)\r\n  .collect(Collectors.toList())\r\n\r\n8. THREADS\r\nextends Thread\r\nimplements Runnable\r\nsynchronized\r\n\r\n9. JDBC\r\nConnection, Statement, ResultSet', 'note_244_java_programming.pdf', 'Java.pdf', 1987, 'application/pdf', 445, '2026-10-08 11:16:42'),
(245, 1, 3, 'C Programming', 'Pointers, memory, structures', 'Computer Science', 'C PROGRAMMING\r\n\r\n1. BASICS\r\n#include <stdio.h>\r\nint main() {\r\n  printf(\"Hello\\n\");\r\n  return 0;\r\n}\r\n\r\n2. TYPES\r\nint, float, double, char\r\nunsigned, long\r\n\r\n3. CONTROL\r\nif/else, switch\r\nfor, while, do-while\r\n\r\n4. FUNCTIONS\r\nreturn_type name(params) {\r\n  return value;\r\n}\r\nPrototypes\r\n\r\n5. ARRAYS\r\nint a[10];\r\nMulti-dimensional\r\n\r\n6. POINTERS\r\nint *p = &x;\r\n*p = 10;\r\nPointer arithmetic\r\n\r\n7. STRINGS\r\nchar s[] = \"hello\";\r\nstrlen, strcpy, strcmp\r\n\r\n8. STRUCTURES\r\nstruct Point {\r\n  int x, y;\r\n};\r\ntypedef\r\n\r\n9. MEMORY\r\nmalloc, calloc, realloc, free\r\nStack vs Heap\r\n\r\n10. FILE I/O\r\nFILE *f = fopen(\"a.txt\", \"r\");\r\nfscanf, fprintf\r\nfclose', 'note_245_c_programming.pdf', 'C.pdf', 1774, 'application/pdf', 512, '2026-10-08 11:16:42'),
(246, 1, 3, 'Web Development', 'HTML, CSS, JavaScript', 'Computer Science', 'WEB DEVELOPMENT\r\n\r\n1. HTML5\r\nStructure: <!DOCTYPE html>\r\nSemantic: header, nav, main, section, article, footer\r\nForms: input, textarea, select\r\nInput types: text, email, password, number, date\r\n\r\n2. CSS3\r\nBox model: content, padding, border, margin\r\nDisplay: block, inline, flex, grid, none\r\n\r\nFlexbox:\r\n  display: flex;\r\n  justify-content: center;\r\n  align-items: center;\r\n\r\nGrid:\r\n  display: grid;\r\n  grid-template-columns: repeat(3, 1fr);\r\n\r\nColors: hex, rgb, rgba, hsl\r\nGradients, Shadows, Transitions\r\nMedia queries: @media (max-width: 768px)\r\n\r\n3. JAVASCRIPT\r\nlet, const\r\nArrow: () => {}\r\nTemplate: `Hi ${name}`\r\n\r\nArrays: map, filter, reduce\r\nObjects, Destructuring, Spread\r\n\r\nDOM:\r\n  getElementById, querySelector\r\n  textContent, innerHTML\r\n  classList, style\r\n  addEventListener\r\n\r\nAsync:\r\n  fetch(url).then().catch()\r\n  async/await\r\n\r\n4. HTTP\r\nMethods: GET, POST, PUT, DELETE\r\nStatus: 200, 404, 500\r\nREST API, JSON', 'note_246_web_development.pdf', 'Web.pdf', 2047, 'application/pdf', 512, '2026-10-08 11:16:42'),
(247, 1, 3, 'Computer Networks', 'OSI, TCP/IP, protocols', 'Computer Science', 'COMPUTER NETWORKS\r\n\r\n1. OSI MODEL\r\n7. Application\r\n6. Presentation\r\n5. Session\r\n4. Transport\r\n3. Network\r\n2. Data Link\r\n1. Physical\r\n\r\n2. TCP/IP\r\n4. Application (5-7)\r\n3. Transport\r\n2. Internet\r\n1. Network Access\r\n\r\n3. TCP vs UDP\r\nTCP: connection, reliable, ordered\r\nUDP: connectionless, fast\r\n\r\nTCP handshake: SYN, SYN-ACK, ACK\r\n\r\n4. IP ADDRESSING\r\nIPv4: 32-bit\r\nIPv6: 128-bit\r\nClasses A-E\r\nPrivate: 10.x, 172.16-31.x, 192.168.x\r\nCIDR: 192.168.1.0/24\r\nNAT, DHCP, DNS\r\n\r\n5. PROTOCOLS\r\nHTTP/HTTPS (80/443)\r\nFTP (21), SFTP (22)\r\nSMTP (25), POP3 (110), IMAP (143)\r\nDNS (53), DHCP (67/68)\r\nSSH (22), Telnet (23)\r\n\r\n6. ROUTING\r\nStatic vs Dynamic\r\nRIP, OSPF, BGP\r\nDijkstra, Bellman-Ford\r\n\r\n7. DEVICES\r\nHub, Switch, Router, Bridge, Gateway\r\nFirewall, Modem, Access Point\r\n\r\n8. WIRELESS\r\n802.11 (WiFi)\r\nWEP, WPA, WPA2, WPA3\r\nBluetooth, Cellular', 'note_247_computer_networks.pdf', 'Networks.pdf', 2007, 'application/pdf', 389, '2026-10-08 11:16:42'),
(248, 1, 3, 'Software Engineering', 'SDLC, Agile, testing', 'Computer Science', 'SOFTWARE ENGINEERING\r\n\r\n1. SDLC\r\nRequirements → Design → Implementation\r\n→ Testing → Deployment → Maintenance\r\n\r\n2. MODELS\r\nWaterfall (linear)\r\nIncremental\r\nSpiral (risk-driven)\r\nAgile (iterative)\r\nScrum, Kanban\r\n\r\n3. REQUIREMENTS\r\nFunctional\r\nNon-functional\r\nUse cases, User stories\r\n\r\n4. DESIGN\r\nSOLID principles:\r\n  Single Responsibility\r\n  Open/Closed\r\n  Liskov Substitution\r\n  Interface Segregation\r\n  Dependency Inversion\r\n\r\nDesign patterns:\r\n  Creational: Singleton, Factory\r\n  Structural: Adapter, Decorator\r\n  Behavioral: Observer, Strategy\r\n\r\n5. TESTING\r\nUnit, Integration, System\r\nBlack-box, White-box\r\nTDD, BDD\r\nJUnit, pytest\r\n\r\n6. VERSION CONTROL\r\nGit: init, clone, add, commit, push, pull\r\nBranching: feature, main\r\nMerge, Rebase, PR\r\n\r\n7. CI/CD\r\nJenkins, GitHub Actions\r\nDocker, Kubernetes', 'note_248_software_engineering.pdf', 'SE.pdf', 1930, 'application/pdf', 234, '2026-10-08 11:16:42'),
(249, 1, 3, 'Cyber Security', 'Encryption, attacks, defense', 'Computer Science', 'CYBER SECURITY\r\n\r\n1. CIA TRIAD\r\nConfidentiality\r\nIntegrity\r\nAvailability\r\n\r\n2. CRYPTOGRAPHY\r\nSymmetric: AES, DES\r\nAsymmetric: RSA, ECC\r\nHash: SHA-256, MD5\r\nDigital signatures\r\nPKI, Certificates\r\n\r\n3. ATTACKS\r\nPhishing\r\nSQL Injection\r\nXSS (Cross-site scripting)\r\nCSRF\r\nMITM\r\nDDoS\r\nRansomware\r\nSocial engineering\r\nPassword attacks\r\n\r\n4. DEFENSE\r\nFirewalls\r\nIDS/IPS\r\nVPN\r\nAntivirus\r\nMFA\r\nEncryption\r\nRegular updates\r\nLeast privilege\r\n\r\n5. AUTHENTICATION\r\nPasswords (bcrypt, argon2)\r\nOAuth 2.0\r\nJWT\r\nBiometrics\r\nSSO\r\n\r\n6. NETWORK SECURITY\r\nHTTPS (TLS)\r\nIPsec\r\nWPA3\r\nPort security\r\nNetwork segmentation\r\n\r\n7. WEB SECURITY\r\nOWASP Top 10\r\nInput validation\r\nOutput encoding\r\nCSRF tokens\r\nCSP headers\r\nSameSite cookies', 'note_249_cyber_security.pdf', 'Security.pdf', 1873, 'application/pdf', 345, '2026-10-08 11:16:42'),
(250, 1, 3, 'Cloud Computing', 'AWS, Azure, GCP basics', 'Computer Science', 'CLOUD COMPUTING\r\n\r\n1. MODELS\r\nIaaS: Infrastructure (EC2)\r\nPaaS: Platform (Heroku)\r\nSaaS: Software (Gmail)\r\n\r\n2. DEPLOYMENT\r\nPublic (AWS, Azure, GCP)\r\nPrivate (on-premise)\r\nHybrid\r\nCommunity\r\n\r\n3. AWS SERVICES\r\nEC2: Virtual machines\r\nS3: Storage\r\nRDS: Databases\r\nLambda: Serverless\r\nCloudFront: CDN\r\nRoute 53: DNS\r\nIAM: Access control\r\nVPC: Networking\r\n\r\n4. VIRTUALIZATION\r\nHypervisor: Type 1, Type 2\r\nContainers: Docker\r\nOrchestration: Kubernetes\r\n\r\n5. SCALING\r\nVertical: bigger machine\r\nHorizontal: more machines\r\nAuto-scaling\r\nLoad balancers\r\n\r\n6. STORAGE\r\nBlock (EBS)\r\nFile (EFS)\r\nObject (S3)\r\n\r\n7. DATABASES\r\nRelational (RDS)\r\nNoSQL (DynamoDB)\r\nData warehouse (Redshift)\r\n\r\n8. COST\r\nOn-demand\r\nReserved\r\nSpot instances\r\nFree tier', 'note_250_cloud_computing.pdf', 'Cloud.pdf', 1893, 'application/pdf', 267, '2026-10-08 11:16:42'),
(251, 1, 3, 'DevOps', 'CI/CD, containers, monitoring', 'Computer Science', 'DEVOPS\r\n\r\n1. PRINCIPLES\r\nCollaboration\r\nAutomation\r\nContinuous improvement\r\nMeasure everything\r\n\r\n2. CI/CD\r\nContinuous Integration\r\n  Build, test on every commit\r\nContinuous Delivery\r\n  Deploy to staging automatically\r\nContinuous Deployment\r\n  Deploy to production automatically\r\n\r\nTools: Jenkins, GitLab CI, GitHub Actions, CircleCI\r\n\r\n3. CONTAINERS\r\nDocker:\r\n  Dockerfile\r\n  docker build, run, push\r\n  Docker Hub\r\n\r\nKubernetes:\r\n  Pods, Services, Deployments\r\n  ConfigMaps, Secrets\r\n  kubectl commands\r\n  Helm charts\r\n\r\n4. INFRASTRUCTURE AS CODE\r\nTerraform\r\nAnsible\r\nCloudFormation\r\nPulumi\r\n\r\n5. MONITORING\r\nPrometheus + Grafana\r\nELK Stack (Elasticsearch, Logstash, Kibana)\r\nDatadog\r\nNew Relic\r\n\r\n6. VERSION CONTROL\r\nGit workflow\r\nFeature branches\r\nCode review\r\nSemantic versioning\r\n\r\n7. CONFIG MANAGEMENT\r\nAnsible playbooks\r\nChef, Puppet\r\nEnvironment variables', 'note_251_devops.pdf', 'DevOps.pdf', 1983, 'application/pdf', 198, '2026-10-08 11:16:42'),
(252, 1, 4, 'Organic Chemistry', 'Reactions, mechanisms', 'Chemistry', 'ORGANIC CHEMISTRY\r\n\r\n1. HYDROCARBONS\r\nAlkanes: substitution (UV)\r\nAlkenes: addition (H₂, Br₂, HBr, H₂O)\r\n  Markovnikov\'s rule\r\nAlkynes: addition, hydration\r\n\r\n2. ALCOHOLS\r\nOxidation: 1°→aldehyde→acid, 2°→ketone\r\nDehydration: → alkene\r\nEsterification: ROH + RCOOH\r\nLucas, Iodoform tests\r\n\r\n3. ALDEHYDES/KETONES\r\nNucleophilic addition\r\n+HCN → cyanohydrin\r\n+Grignard → alcohol\r\nReduction → alcohol\r\nTollens: silver mirror\r\nFehling: red ppt\r\nIodoform: methyl ketones\r\n\r\n4. CARBOXYLIC ACIDS\r\n+ROH → ester\r\n+PCl₅ → acid chloride\r\nReduction → 1° alcohol\r\nReactivity: AcylCl > Anhyd > Ester > Amide\r\n\r\n5. AMINES\r\nBasic\r\n+Acid → salt\r\nHinsberg, Carbylamine tests\r\n\r\n6. AROMATIC\r\nElectrophilic substitution:\r\n  Nitration, Halogenation, Sulfonation\r\n  Friedel-Crafts\r\nActivating (o/p): OH, NH₂, OR, R\r\nDeactivating (m): NO₂, CN, COOH\r\n\r\n7. STEREOCHEMISTRY\r\nChiral center: 4 different groups\r\nEnantiomers, Diastereomers\r\nR/S configuration\r\nE/Z alkenes\r\n\r\n8. MECHANISMS\r\nSN1: 2 steps, carbocation\r\nSN2: 1 step, inversion\r\nE1, E2', 'note_252_organic_chemistry.pdf', 'Organic.pdf', 2040, 'application/pdf', 356, '2026-10-08 11:16:42'),
(253, 1, 4, 'Periodic Table', 'Groups, trends, elements', 'Chemistry', 'PERIODIC TABLE\r\n\r\n1. STRUCTURE\r\n7 periods × 18 groups\r\ns, p, d, f blocks\r\n\r\n2. GROUPS\r\nGroup 1: Alkali, +1\r\nGroup 2: Alkaline earth, +2\r\nGroup 17: Halogens, -1\r\nGroup 18: Noble, inert\r\n\r\n3. TRENDS\r\nProperty         | L→R       | T→B\r\nAtomic radius    | Decreases | Increases\r\nIonization E     | Increases | Decreases\r\nElectron affinity| Increases | Decreases\r\nElectronegativity| Increases | Decreases\r\nMetallic char    | Decreases | Increases\r\n\r\n4. ELECTRON CONFIG\r\nAufbau: lowest first\r\nPauli: max 2 per orbital\r\nHund: single fill first\r\n\r\nOrder: 1s 2s 2p 3s 3p 4s 3d 4p 5s 4d 5p 6s 4f 5d 6p\r\n\r\nExamples:\r\n  H: 1s¹\r\n  C: 1s² 2s² 2p²\r\n  Na: [Ne] 3s¹\r\n  Fe: [Ar] 3d⁶ 4s²\r\n\r\n5. IMPORTANT ELEMENTS\r\nH (most abundant), He, C (organic), N (78% air), O (21%)\r\nNa, K (nerve), Ca (bones), Fe (Hb), Cu (wires)\r\n\r\n6. ALLOYS\r\nSteel: Fe+C\r\nBronze: Cu+Sn\r\nBrass: Cu+Zn\r\nStainless: Fe+Cr+Ni', 'note_253_periodic_table.pdf', 'Periodic.pdf', 1722, 'application/pdf', 489, '2026-10-08 11:16:42'),
(254, 1, 4, 'Chemical Bonding', 'Ionic, covalent, VSEPR', 'Chemistry', 'CHEMICAL BONDING\r\n\r\n1. TYPES\r\nIonic: metal + nonmetal\r\nCovalent: nonmetals\r\nMetallic: sea of e⁻\r\nCoordinate: both e⁻ from one atom\r\n\r\n2. LEWIS STRUCTURES\r\nCount valence, arrange, connect,\r\nadd lone pairs, check octets\r\n\r\nExceptions:\r\n  Be, B (6 e⁻)\r\n  P, S, Cl (expanded)\r\n  NO, NO₂ (odd)\r\n\r\nResonance: O₃, CO₃²⁻, NO₃⁻\r\n\r\n3. VSEPR\r\nAX₂: Linear (180°)\r\nAX₃: Trigonal (120°)\r\nAX₄: Tetrahedral (109.5°)\r\nAX₃E: Pyramidal (107°)\r\nAX₂E₂: Bent (104.5°)\r\nAX₅: Trig bipyramidal\r\nAX₆: Octahedral\r\n\r\nLP-LP > LP-BP > BP-BP\r\n\r\n4. HYBRIDIZATION\r\nsp, sp², sp³, sp³d, sp³d²\r\n\r\n5. MO THEORY\r\nBonding < Antibonding\r\nBond order = (b-a)/2\r\n\r\nO₂: BO=2, paramagnetic\r\nN₂: BO=3, very stable\r\n\r\n6. POLARITY\r\nΔEN: 0-0.4 nonpolar\r\n0.4-1.7 polar\r\n>1.7 ionic\r\n\r\nSymmetric → nonpolar\r\nAsymmetric → polar\r\n\r\n7. IMF\r\nLondon < Dipole < H-bond < Ion-dipole', 'note_254_chemical_bonding.pdf', 'Bonding.pdf', 1652, 'application/pdf', 201, '2026-10-08 11:16:42'),
(255, 1, 4, 'Thermochemistry', 'Enthalpy, entropy, Gibbs', 'Chemistry', 'THERMOCHEMISTRY\r\n\r\n1. FIRST LAW\r\nΔE = q + w\r\nAt constant V: ΔE = q_v\r\nAt constant P: ΔH = q_p\r\n\r\n2. ENTHALPY\r\nExothermic: ΔH < 0\r\nEndothermic: ΔH > 0\r\n\r\nStandard: ΔH°f\r\nElements: ΔH°f = 0\r\n\r\nHess\'s Law:\r\nΔH°rxn = ΣnΔH°f(prod) - ΣnΔH°f(react)\r\n\r\nCommon ΔH°f (kJ/mol):\r\nH₂O(l): -285.8\r\nH₂O(g): -241.8\r\nCO₂(g): -393.5\r\nCH₄(g): -74.8\r\n\r\n3. CALORIMETRY\r\nq = mcΔT\r\n\r\nSpecific heats (J/g°C):\r\nWater: 4.184\r\nAluminum: 0.900\r\nCopper: 0.387\r\n\r\n4. ENTROPY\r\nΔS > 0 for spontaneous\r\nGas > Liquid > Solid\r\nΔS°rxn = ΣS°(prod) - ΣS°(react)\r\n\r\n5. GIBBS\r\nΔG = ΔH - TΔS\r\nΔG < 0: spontaneous\r\nΔG = 0: equilibrium\r\nΔG > 0: non-spontaneous\r\n\r\nΔG° = -RT ln K', 'note_255_thermochemistry.pdf', 'ThermoChem.pdf', 1362, 'application/pdf', 178, '2026-10-08 11:16:42'),
(256, 1, 4, 'Acids & Bases', 'pH, buffers, titrations', 'Chemistry', 'ACIDS & BASES\r\n\r\n1. DEFINITIONS\r\nArrhenius: H⁺, OH⁻\r\nBronsted-Lowry: proton donor/acceptor\r\nLewis: electron pair acceptor/donor\r\n\r\n2. pH\r\npH = -log[H⁺]\r\npOH = -log[OH⁻]\r\npH + pOH = 14\r\n\r\n[H⁺][OH⁻] = 10⁻¹⁴\r\n\r\nStrong acids: HCl, HBr, HI, HNO₃, H₂SO₄, HClO₄\r\nStrong bases: LiOH, NaOH, KOH, Ca(OH)₂\r\n\r\n3. Ka, Kb\r\nKa = [H⁺][A⁻]/[HA]\r\npKa = -log Ka\r\nLower pKa → stronger acid\r\n\r\nKb = [BH⁺][OH⁻]/[B]\r\nKw = Ka × Kb = 10⁻¹⁴\r\n\r\n4. BUFFERS\r\nHenderson-Hasselbalch:\r\npH = pKa + log([A⁻]/[HA])\r\n\r\n5. TITRATION\r\nEquivalence: moles acid = moles base\r\nCurve types: strong/strong, weak/strong\r\nIndicators:\r\n  Phenolphthalein: 8.2-10\r\n  Methyl orange: 3.1-4.4\r\n\r\n6. SOLUBILITY\r\nKsp = product of ion concentrations\r\nCommon ion effect', 'note_256_acids_bases.pdf', 'Acids.pdf', 1322, 'application/pdf', 234, '2026-10-08 11:16:42'),
(257, 1, 4, 'Electrochemistry', 'Redox, cells, electrolysis', 'Chemistry', 'ELECTROCHEMISTRY\r\n\r\n1. REDOX\r\nOxidation: loss of e⁻\r\nReduction: gain of e⁻\r\nOIL RIG (Oxidation Is Loss)\r\n\r\n2. OXIDATION NUMBERS\r\nFree element: 0\r\nMonatomic ion: charge\r\nO usually: -2\r\nH usually: +1\r\nSum in molecule = charge\r\n\r\n3. GALVANIC CELL\r\nAnode: oxidation (-)\r\nCathode: reduction (+)\r\n\r\nCell notation:\r\nZn | Zn²⁺ || Cu²⁺ | Cu\r\n\r\nEMF: E°cell = E°cathode - E°anode\r\n\r\n4. NERNST EQUATION\r\nE = E° - (RT/nF)lnQ\r\nE = E° - (0.0592/n)logQ at 25°C\r\n\r\n5. STANDARD REDUCTION POTENTIALS\r\nLi⁺/Li: -3.05 V\r\nZn²⁺/Zn: -0.76 V\r\nH⁺/H₂: 0 V (reference)\r\nCu²⁺/Cu: +0.34 V\r\nAg⁺/Ag: +0.80 V\r\nAu³⁺/Au: +1.50 V\r\n\r\n6. ELECTROLYSIS\r\nFaraday\'s laws\r\nF = 96500 C/mol\r\nUsed for plating, refining\r\n\r\n7. BATTERIES\r\nDry cell (1.5 V)\r\nLead-acid (2 V/cell)\r\nLithium-ion (3.7 V)\r\nFuel cells', 'note_257_electrochemistry.pdf', 'Electro.pdf', 1733, 'application/pdf', 156, '2026-10-08 11:16:42'),
(258, 1, 4, 'Chemical Kinetics', 'Rates, order, mechanisms', 'Chemistry', 'CHEMICAL KINETICS\r\n\r\n1. RATE\r\nRate = -Δ[A]/Δt = Δ[B]/Δt\r\nRate = k[A]^m[B]^n\r\nm+n = overall order\r\n\r\n2. RATE LAWS\r\nZero order: [A] = [A]₀ - kt\r\nFirst order: ln[A] = ln[A]₀ - kt\r\n  t₁/₂ = 0.693/k\r\nSecond order: 1/[A] = 1/[A]₀ + kt\r\n\r\n3. ARRHENIUS\r\nk = A·e^(-Ea/RT)\r\nln(k₂/k₁) = (Ea/R)(1/T₁ - 1/T₂)\r\n\r\n4. COLLISION THEORY\r\nRate ∝ collision frequency\r\nEffective collisions (proper orientation)\r\n\r\n5. MECHANISMS\r\nElementary steps\r\nRate-determining step\r\nMolecularity\r\n\r\n6. CATALYSIS\r\nHomogeneous\r\nHeterogeneous\r\nEnzymes (biological)\r\nLower Ea, not ΔH\r\n\r\n7. FACTORS\r\nConcentration\r\nTemperature (+10°C → 2x rate)\r\nSurface area\r\nCatalyst\r\nPressure (gases)', 'note_258_chemical_kinetics.pdf', 'Kinetics.pdf', 1294, 'application/pdf', 145, '2026-10-08 11:16:42'),
(259, 1, 5, 'Human Anatomy', 'Body systems overview', 'Biology', 'HUMAN ANATOMY\r\n\r\n1. SKELETAL\r\n206 bones\r\nAxial (80): skull, vertebral, ribs\r\nAppendicular (126): limbs, girdles\r\n\r\nTypes: Long, Short, Flat, Irregular, Sesamoid\r\nJoints: Fibrous, Cartilaginous, Synovial\r\n\r\n2. MUSCULAR\r\nSkeletal: voluntary\r\nSmooth: involuntary\r\nCardiac: heart\r\n\r\nBiceps, Triceps, Deltoid, Pectoralis\r\nQuadriceps, Hamstrings, Gastrocnemius\r\n\r\n3. CIRCULATORY\r\nHeart: 4 chambers\r\nArteries, Veins, Capillaries\r\nBlood: Plasma, RBCs, WBCs, Platelets\r\nCirculation: Pulmonary, Systemic\r\n\r\n4. RESPIRATORY\r\nNose → Alveoli\r\nAlveoli: 300M, 70m²\r\nTidal 500mL, Vital 4700mL\r\n\r\n5. DIGESTIVE\r\nMouth → Anus\r\nLiver, Pancreas, Gallbladder\r\nPeristalsis\r\nVilli absorption\r\n\r\n6. NERVOUS\r\nCNS: Brain, Spinal cord\r\nPNS: Somatic, Autonomic\r\nNeuron, Synapse\r\n\r\n7. URINARY\r\nKidneys, ureters, bladder, urethra\r\nNephron: filter 180L/day\r\n\r\n8. ENDOCRINE\r\nPituitary, Thyroid, Adrenal\r\nInsulin, Glucagon, Cortisol', 'note_259_human_anatomy.pdf', 'Anatomy.pdf', 2025, 'application/pdf', 578, '2026-10-08 11:16:42'),
(260, 1, 5, 'Cell Biology', 'Cell structure and function', 'Biology', 'CELL BIOLOGY\r\n\r\n1. CELL THEORY\r\nAll living = cells\r\nBasic unit of life\r\nCells from cells\r\n\r\n2. PROKARYOTIC vs EUKARYOTIC\r\nPro: no nucleus, circular DNA, 1-10μm\r\nEuk: nucleus, linear DNA, 10-100μm\r\n\r\n3. ORGANELLES\r\nNucleus: DNA\r\nMitochondria: ATP\r\nRibosomes: protein\r\nRough ER: protein synth\r\nSmooth ER: lipids\r\nGolgi: packaging\r\nLysosomes: digestion\r\nVacuoles: storage\r\nChloroplasts: photosynthesis\r\nCell wall: cellulose\r\n\r\n4. MEMBRANE\r\nFluid mosaic: phospholipid + proteins + cholesterol\r\n\r\nTransport:\r\n  Passive: diffusion, osmosis, facilitated\r\n  Active: Na-K pump\r\n\r\nTonicity: hyper/hypo/isotonic\r\n\r\n5. DIVISION\r\nMitosis: 2 identical cells\r\nInterphase, Prophase, Metaphase, Anaphase, Telophase\r\n\r\nMeiosis: 4 haploid cells\r\nCrossing over, independent assortment\r\n\r\n6. TRANSPORT\r\nEndocytosis, Exocytosis\r\nPhagocytosis, Pinocytosis', 'note_260_cell_biology.pdf', 'CellBio.pdf', 1605, 'application/pdf', 412, '2026-10-08 11:16:42'),
(261, 1, 5, 'Genetics', 'DNA, inheritance, mutations', 'Biology', 'GENETICS\r\n\r\n1. DNA STRUCTURE\r\nDouble helix (Watson & Crick)\r\nSugar-phosphate backbone\r\nBases: A=T, G≡C\r\nPurines: A, G\r\nPyrimidines: C, T\r\nHuman: 46 chromosomes\r\n\r\n2. REPLICATION\r\nSemi-conservative\r\nHelicase, Primase, Polymerase, Ligase\r\n5\'→3\'\r\n\r\n3. TRANSCRIPTION\r\nDNA → mRNA\r\nRNA polymerase\r\nPromoter, Terminator\r\nIntrons removed, Exons joined\r\n5\' cap, Poly-A tail\r\n\r\n4. TRANSLATION\r\nmRNA → Protein\r\nRibosome, tRNA\r\nCodon = 3 nucleotides\r\nStart: AUG\r\nStop: UAA, UAG, UGA\r\n64 codons → 20 amino acids\r\n\r\n5. MENDEL\r\nSegregation\r\nIndependent assortment\r\nMonohybrid: 3:1\r\nDihybrid: 9:3:3:1\r\n\r\n6. VARIATIONS\r\nIncomplete dominance\r\nCodominance\r\nMultiple alleles (ABO)\r\nPolygenic\r\nSex-linked\r\n\r\n7. MUTATIONS\r\nPoint: Silent, Missense, Nonsense\r\nFrameshift\r\nChromosomal: Del, Dup, Inv, Trans\r\n\r\n8. DNA TECHNOLOGY\r\nPCR, Gel electrophoresis\r\nCRISPR, Cloning\r\nGenetic testing', 'note_261_genetics.pdf', 'Genetics.pdf', 1986, 'application/pdf', 389, '2026-10-08 11:16:42'),
(262, 1, 5, 'Ecology', 'Ecosystems, biomes, cycles', 'Biology', 'ECOLOGY\r\n\r\n1. LEVELS\r\nOrganism → Population → Community\r\n→ Ecosystem → Biome → Biosphere\r\n\r\n2. ECOSYSTEM\r\nBiotic: Producers, Consumers, Decomposers\r\nAbiotic: Sun, Water, Temp, Soil\r\nEnergy flow: 10% rule\r\nFood chain, Food web\r\nTrophic levels 1-4\r\n\r\n3. CYCLES\r\nWater: Evaporation, Condensation, Precipitation\r\nCarbon: Photosynthesis, Respiration, Combustion\r\nNitrogen: Fixation, Nitrification, Denitrification\r\nPhosphorus: Rock weathering\r\n\r\n4. POPULATION\r\nExponential: dN/dt = rN\r\nLogistic: dN/dt = rN(K-N)/K\r\nSurvivorship: I, II, III\r\nAge structure\r\n\r\n5. COMMUNITY\r\nCompetition (-/-)\r\nPredation (+/-)\r\nMutualism (+/+)\r\nCommensalism (+/0)\r\nParasitism (+/-)\r\nSuccession: Primary, Secondary\r\n\r\n6. BIOMES\r\nTropical Rainforest\r\nSavanna, Desert\r\nTemperate Grassland, Deciduous\r\nTaiga, Tundra\r\n\r\n7. ENVIRONMENT\r\nPollution, Climate Change\r\nOzone, Deforestation\r\nConservation', 'note_262_ecology.pdf', 'Ecology.pdf', 1987, 'application/pdf', 156, '2026-10-08 11:16:42'),
(263, 1, 5, 'Human Physiology', 'Organ system functions', 'Biology', 'HUMAN PHYSIOLOGY\r\n\r\n1. HOMEOSTASIS\r\nTemp: 37°C\r\npH: 7.35-7.45\r\nGlucose: 70-110 mg/dL\r\nBP: 120/80\r\n\r\nFeedback: Negative (main), Positive\r\n\r\n2. NERVOUS\r\nAction potential: -70 → -55 → +30 mV\r\nDepolarization (Na⁺ in)\r\nRepolarization (K⁺ out)\r\n\r\nNeurotransmitters:\r\n  ACh: muscle\r\n  Dopamine: reward\r\n  Serotonin: mood\r\n  GABA: inhibitory\r\n  Glutamate: excitatory\r\n\r\n3. ENDOCRINE\r\nPituitary: GH, TSH, ACTH\r\nThyroid: T3, T4\r\nAdrenal: Cortisol, Adrenaline\r\nPancreas: Insulin, Glucagon\r\n\r\n4. CARDIOVASCULAR\r\nCO = HR × SV\r\n~5 L/min\r\nBP: 120/80\r\n\r\n5. RESPIRATORY\r\nTidal: 500 mL\r\nVital: 4700 mL\r\nO₂ on hemoglobin (98%)\r\nCO₂ as bicarbonate (70%)\r\n\r\n6. DIGESTIVE\r\nMouth: amylase\r\nStomach: pepsin, pH 2\r\nSI: absorption\r\nLI: water\r\n\r\n7. URINARY\r\nFilter 180 L/day\r\nUrine 1.5 L/day\r\nADH, Aldosterone\r\n\r\n8. IMMUNE\r\nInnate: skin, phagocytes\r\nAdaptive: B cells, T cells\r\nAntibodies, Memory', 'note_263_human_physiology.pdf', 'Physiology.pdf', 1916, 'application/pdf', 334, '2026-10-08 11:16:42'),
(264, 1, 5, 'Microbiology', 'Bacteria, viruses, fungi', 'Biology', 'MICROBIOLOGY\r\n\r\n1. BACTERIA\r\nProkaryotic\r\nShapes: cocci, bacilli, spirilla\r\nGram +ve: thick peptidoglycan (purple)\r\nGram -ve: thin + outer membrane (pink)\r\nReproduction: binary fission\r\nPathogenic: TB, cholera, tetanus\r\nBeneficial: gut flora, nitrogen fixation\r\n\r\n2. VIRUSES\r\nAcellular\r\nDNA or RNA + protein coat\r\nObligate intracellular parasites\r\nLytic vs Lysogenic\r\nExamples: HIV, Influenza, COVID-19, Herpes\r\n\r\n3. FUNGI\r\nEukaryotic\r\nYeasts (unicellular), Molds (multicellular)\r\nCell wall: chitin\r\nReproduction: spores\r\nExamples: Candida, Aspergillus\r\nBeneficial: Penicillin, yeast in bread\r\n\r\n4. PROTOZOA\r\nUnicellular eukaryotes\r\nMalaria (Plasmodium)\r\nAmoeba, Paramecium\r\n\r\n5. IMMUNITY\r\nInnate: skin, mucus, phagocytes\r\nAdaptive: B cells, T cells\r\nVaccines: attenuated, inactivated, subunit\r\nAntibiotics: cell wall, protein synthesis\r\n\r\n6. CULTURE\r\nNutrient agar\r\nStreak plate\r\nIncubation 37°C\r\nSterilization: autoclave', 'note_264_microbiology.pdf', 'Micro.pdf', 1780, 'application/pdf', 189, '2026-10-08 11:16:42'),
(265, 1, 5, 'Biotechnology', 'Genetic engineering, applications', 'Biology', 'BIOTECHNOLOGY\r\n\r\n1. TOOLS\r\nRestriction enzymes (molecular scissors)\r\nDNA ligase\r\nVectors: plasmids, viruses\r\nHost: E. coli, yeast\r\n\r\n2. TECHNIQUES\r\nPCR: amplify DNA\r\n  Denature 95°C\r\n  Anneal 55°C\r\n  Extend 72°C\r\nGel electrophoresis: separate DNA\r\nDNA sequencing: Sanger method\r\nCRISPR-Cas9: gene editing\r\n\r\n3. APPLICATIONS\r\nMedicine:\r\n  Insulin production\r\n  Vaccines\r\n  Gene therapy\r\n  Monoclonal antibodies\r\nAgriculture:\r\n  GM crops (Bt cotton, Golden rice)\r\n  Pest resistance\r\nEnvironment:\r\n  Bioremediation\r\n  Biofuels\r\n\r\n4. GENOMICS\r\nHuman Genome Project\r\nBioinformatics\r\nPersonalized medicine\r\n\r\n5. ETHICS\r\nGMO concerns\r\nGene editing (germline)\r\nCloning\r\nPrivacy of genetic data', 'note_265_biotechnology.pdf', 'Biotech.pdf', 1511, 'application/pdf', 145, '2026-10-08 11:16:42'),
(266, 1, 6, 'English Grammar', 'Parts of speech, tenses', 'English', 'ENGLISH GRAMMAR\r\n\r\n1. PARTS OF SPEECH\r\nNoun: Common, Proper, Abstract, Collective\r\nPronoun: Personal, Possessive, Reflexive\r\nVerb: Action, Linking, Helping\r\nAdjective: Descriptive, Comparative\r\nAdverb: Manner, Time, Place, Frequency\r\nPreposition: at, on, in, under, over\r\nConjunction: and, but, or, because\r\nInterjection: Wow!, Oh!\r\n\r\n2. TENSES\r\nSimple Present: I work\r\nPresent Continuous: I am working\r\nPresent Perfect: I have worked\r\nPresent Perfect Cont: I have been working\r\n\r\nSimple Past: I worked\r\nPast Continuous: I was working\r\nPast Perfect: I had worked\r\n\r\nSimple Future: I will work\r\nFuture Continuous: I will be working\r\nFuture Perfect: I will have worked\r\n\r\n3. ARTICLES\r\na: consonant sound (a book)\r\nan: vowel sound (an hour)\r\nthe: specific, unique\r\nNo article: plural general\r\n\r\n4. PREPOSITIONS\r\nTime: at (5pm), on (Monday), in (May)\r\nPlace: at (point), in (enclosed), on (surface)\r\nCollocations: good at, interested in\r\n\r\n5. VOICE\r\nActive: The cat killed the mouse\r\nPassive: The mouse was killed by the cat\r\n\r\n6. NARRATION\r\nDirect: He said, \"I am happy\"\r\nIndirect: He said he was happy\r\n\r\n7. COMMON ERRORS\r\nHe go → He goes\r\nMarried with → Married to\r\nMore better → Better', 'note_266_english_grammar.pdf', 'Grammar.pdf', 2334, 'application/pdf', 523, '2026-10-08 11:16:42'),
(267, 1, 6, 'Essay Writing', 'Structure and style', 'English', 'ESSAY WRITING\r\n\r\n1. STRUCTURE\r\nIntroduction:\r\n  Hook, Background, Thesis (last sentence)\r\n\r\nBody (2-4 paragraphs):\r\n  Topic sentence\r\n  Evidence\r\n  Analysis\r\n  Concluding sentence\r\n\r\nConclusion:\r\n  Restate thesis\r\n  Summarize\r\n  Final thought\r\n\r\n2. TYPES\r\nNarrative, Descriptive, Expository, Persuasive\r\nCompare/Contrast, Cause/Effect\r\n\r\n3. THESIS\r\nWeak: Pollution is bad\r\nStrong: Government should regulate single-use plastics\r\n\r\n4. PEEL\r\nPoint, Evidence, Explain, Link\r\n\r\n5. TRANSITIONS\r\nAddition: Furthermore, Moreover\r\nContrast: However, Nevertheless\r\nCause: Therefore, Consequently\r\nExample: For instance\r\nConclusion: In conclusion\r\n\r\n6. EVIDENCE\r\nStatistics, Expert quotes, Studies\r\nIntegrate quotes properly\r\n\r\n7. STYLE\r\nFormal: no contractions, no slang\r\nClarity: short sentences, active voice\r\nPrecise words, vary sentences\r\n\r\n8. COMMON MISTAKES\r\nNo clear thesis\r\nWeak intro\r\nOff-topic\r\nNo evidence\r\nWeak conclusion', 'note_267_essay_writing.pdf', 'Essay.pdf', 2043, 'application/pdf', 289, '2026-10-08 11:16:42'),
(268, 1, 6, 'Vocabulary Builder', 'Words and usage', 'English', 'VOCABULARY BUILDER\r\n\r\n1. WORD ROOTS\r\nLatin:\r\n  dict (say) → dictate, predict, contradict\r\n  port (carry) → transport, export, report\r\n  vid/vis (see) → video, vision, visible\r\n  aud (hear) → audio, audience, audible\r\n\r\nGreek:\r\n  bio (life) → biology, biography\r\n  geo (earth) → geology, geography\r\n  phon (sound) → telephone, phonics\r\n  graph (write) → photograph, biography\r\n\r\n2. PREFIXES\r\nun-, in-, im-: not\r\nre-: again\r\npre-: before\r\npost-: after\r\nanti-: against\r\nsub-: under\r\nsuper-: above\r\n\r\n3. SUFFIXES\r\n-able, -ible: capable of\r\n-tion, -sion: act of\r\n-ness: state\r\n-ment: result\r\n-ify: make\r\n\r\n4. COMMON WORDS\r\nAberration: deviation\r\nEphemeral: short-lived\r\nUbiquitous: everywhere\r\nSerendipity: lucky discovery\r\nPragmatic: practical\r\nEloquent: fluent\r\nTenacious: persistent\r\n\r\n5. IDIOMS\r\nBreak the ice\r\nBite the bullet\r\nOnce in a blue moon\r\nPiece of cake\r\nUnder the weather\r\nBurn the midnight oil', 'note_268_vocabulary_builder.pdf', 'Vocab.pdf', 2038, 'application/pdf', 234, '2026-10-08 11:16:42'),
(269, 1, 6, 'Reading Comprehension', 'Strategies and practice', 'English', 'READING COMPREHENSION\r\n\r\n1. STRATEGIES\r\nSkimming: get main idea fast\r\nScanning: find specific info\r\nClose reading: detailed analysis\r\nAnnotation: mark key points\r\n\r\n2. QUESTION TYPES\r\nMain idea\r\nDetail\r\nInference\r\nVocabulary in context\r\nAuthor\'s purpose\r\nTone\r\nStructure\r\n\r\n3. MAIN IDEA\r\nOften in first/last paragraph\r\nLook for thesis statement\r\nCheck topic sentences\r\n\r\n4. INFERENCE\r\nRead between lines\r\nWhat\'s implied?\r\nNot directly stated\r\n\r\n5. VOCABULARY IN CONTEXT\r\nLook at surrounding words\r\nCheck connotation\r\nConsider tone\r\n\r\n6. AUTHOR\'S PURPOSE\r\nInform (facts)\r\nPersuade (opinion)\r\nEntertain (story)\r\nExplain (how-to)\r\n\r\n7. TONE\r\nFormal, Informal\r\nCritical, Supportive\r\nObjective, Subjective\r\nOptimistic, Pessimistic\r\n\r\n8. PRACTICE\r\nRead daily (news, articles)\r\nTime yourself\r\nReview mistakes\r\nBuild vocabulary', 'note_269_reading_comprehension.pdf', 'Reading.pdf', 1965, 'application/pdf', 178, '2026-10-08 11:16:42');
INSERT INTO `notes` (`id`, `user_id`, `category_id`, `title`, `description`, `subject`, `content`, `filename`, `original_name`, `filesize`, `filetype`, `downloads`, `created_at`) VALUES
(270, 1, 6, 'Business English', 'Professional communication', 'English', 'BUSINESS ENGLISH\r\n\r\n1. EMAILS\r\nFormal:\r\n  Dear Mr. Smith,\r\n  I am writing to...\r\n  Best regards,\r\n  [Name]\r\n\r\nInformal:\r\n  Hi John,\r\n  Just a quick note...\r\n  Thanks,\r\n  [Name]\r\n\r\n2. MEETINGS\r\nOpening: Let\'s get started\r\nAgenda: Today we\'ll discuss...\r\nInterrupting: Sorry to interrupt\r\nClarifying: Do you mean...?\r\nClosing: Let\'s wrap up\r\n\r\n3. PRESENTATIONS\r\nIntroduction: Today I\'ll talk about...\r\nStructure: First, Second, Finally\r\nVisuals: As you can see...\r\nConclusion: To sum up...\r\n\r\n4. NEGOTIATION\r\nOffering: We could offer...\r\nCountering: That\'s a bit high...\r\nCompromise: What if we...\r\nAgreement: Let\'s agree on...\r\n\r\n5. PHONE CALLS\r\nAnswering: Good morning, XYZ Corp\r\nRequesting: Could I speak to...?\r\nHolding: Please hold on\r\nTransferring: I\'ll put you through\r\n\r\n6. VOCABULARY\r\nDeadline, Milestone\r\nStakeholder, Deliverable\r\nROI, KPI\r\nBenchmark, Best practice\r\nSynergy, Streamline', 'note_270_business_english.pdf', 'Business.pdf', 2000, 'application/pdf', 145, '2026-10-08 11:16:42'),
(271, 1, 7, 'World History', 'Major events timeline', 'History', 'WORLD HISTORY\r\n\r\n1. ANCIENT\r\n3000 BCE: Indus Valley, Egypt, Mesopotamia\r\n776 BCE: First Olympics\r\n563 BCE: Buddha born\r\n336-323 BCE: Alexander the Great\r\n\r\n2. MEDIEVAL\r\n476 CE: Fall of Rome\r\n622 CE: Hijra (Islam)\r\n1066: Norman Conquest\r\n1215: Magna Carta\r\n\r\n3. RENAISSANCE\r\n1450: Printing press (Gutenberg)\r\n1492: Columbus reaches Americas\r\n1498: Vasco da Gama to India\r\n\r\n4. INDUSTRIAL\r\n1776: American Independence\r\n1789: French Revolution\r\n1857: Indian Rebellion\r\n1861-65: American Civil War\r\n\r\n5. WORLD WARS\r\nWWI: 1914-1918\r\n  Treaty of Versailles 1919\r\nWWII: 1939-1945\r\n  Hiroshima, Nagasaki\r\n  UN founded 1945\r\n\r\n6. COLD WAR\r\n1947-1991\r\nNATO vs Warsaw Pact\r\nSpace Race\r\nFall of Berlin Wall 1989\r\nUSSR dissolves 1991\r\n\r\n7. MODERN\r\n1991: India liberalization\r\n2001: 9/11\r\n2008: Financial crisis\r\n2020: COVID-19 pandemic', 'note_271_world_history.pdf', 'WorldHistory.pdf', 1932, 'application/pdf', 234, '2026-10-08 11:16:42'),
(272, 1, 7, 'Indian History', 'Ancient to modern India', 'History', 'INDIAN HISTORY\r\n\r\n1. ANCIENT\r\nIndus Valley: 3300-1300 BCE\r\n  Harappa, Mohenjo-daro\r\nVedic Period: 1500-500 BCE\r\n  Rigveda, caste system\r\nMahajanapadas\r\nMaurya Empire: 322-185 BCE\r\n  Chandragupta, Ashoka\r\nGupta Empire: 320-550 CE\r\n  Golden Age\r\n\r\n2. MEDIEVAL\r\nDelhi Sultanate: 1206-1526\r\n  Slave, Khilji, Tughlaq, Sayyid, Lodi\r\nMughal Empire: 1526-1857\r\n  Babur, Akbar, Shah Jahan, Aurangzeb\r\n  Taj Mahal\r\nMaratha Empire: 1674-1818\r\n  Shivaji Maharaj\r\n\r\n3. BRITISH\r\nBattle of Plassey 1757\r\n1857 Rebellion\r\nINC founded 1885\r\nJallianwala Bagh 1919\r\nNon-Cooperation 1920\r\nDandi March 1930\r\nQuit India 1942\r\n\r\n4. INDEPENDENCE\r\nAugust 15, 1947\r\nPartition: India, Pakistan\r\nGandhi assassinated 1948\r\n\r\n5. MODERN INDIA\r\nConstitution 1950\r\nNehru, Shastri, Indira, Rajiv\r\n1991 Economic reforms\r\nVajpayee, Manmohan Singh\r\nModi era', 'note_272_indian_history.pdf', 'IndianHistory.pdf', 1653, 'application/pdf', 445, '2026-10-08 11:16:42'),
(273, 1, 7, 'Modern History', '20th century events', 'History', 'MODERN HISTORY\r\n\r\n1. WWI (1914-1918)\r\nCauses: Militarism, Alliances, Imperialism, Nationalism\r\nTrigger: Assassination of Archduke Franz Ferdinand\r\nAllies vs Central Powers\r\nTreaty of Versailles (1919)\r\nLeague of Nations\r\n\r\n2. INTERWAR\r\nRoaring Twenties\r\nGreat Depression (1929)\r\nRise of Fascism (Mussolini, Hitler)\r\nSpanish Civil War\r\n\r\n3. WWII (1939-1945)\r\nInvasion of Poland\r\nHolocaust\r\nPearl Harbor (1941)\r\nD-Day (1944)\r\nHiroshima/Nagasaki (1945)\r\nUN founded\r\n\r\n4. COLD WAR\r\nContainment\r\nMarshall Plan\r\nBerlin Blockade\r\nKorean War\r\nCuban Missile Crisis\r\nVietnam War\r\nSpace Race\r\nBerlin Wall falls (1989)\r\nUSSR dissolves (1991)\r\n\r\n5. DECOLONIZATION\r\nIndia (1947)\r\nIsrael (1948)\r\nAfrican independence\r\nAlgeria, Kenya, Ghana\r\n\r\n6. GLOBALIZATION\r\nInternet\r\nEU formed\r\nBRICS\r\nG20\r\nClimate agreements', 'note_273_modern_history.pdf', 'ModernHistory.pdf', 1940, 'application/pdf', 189, '2026-10-08 11:16:42'),
(274, 1, 7, 'American History', 'USA timeline', 'History', 'AMERICAN HISTORY\r\n\r\n1. COLONIAL\r\n1607: Jamestown\r\n1620: Mayflower\r\n13 Colonies\r\nSalutary neglect\r\n\r\n2. REVOLUTION\r\nBoston Tea Party 1773\r\nDeclaration of Independence 1776\r\nTreaty of Paris 1783\r\nConstitution 1787\r\nBill of Rights 1791\r\n\r\n3. EXPANSION\r\nLouisiana Purchase 1803\r\nManifest Destiny\r\nMexican-American War\r\nCivil War 1861-65\r\n  Lincoln, Emancipation\r\nReconstruction\r\n\r\n4. INDUSTRIAL\r\nRailroads, Steel, Oil\r\nRobber Barons\r\nImmigration waves\r\nProgressive Era\r\nWomen\'s suffrage 1920\r\n\r\n5. WORLD POWER\r\nWWI (1917 entry)\r\nWWII (1941 entry)\r\nAtomic bomb\r\nCold War\r\nCivil Rights Movement\r\n  MLK, Rosa Parks\r\nSpace Race\r\nMoon landing 1969\r\n\r\n6. MODERN\r\n1980s Reagan\r\n1990s Clinton\r\n2001 9/11\r\n2008 Obama elected\r\n2020 COVID', 'note_274_american_history.pdf', 'American.pdf', 1844, 'application/pdf', 156, '2026-10-08 11:16:42'),
(275, 1, 8, 'Microeconomics', 'Supply, demand, markets', 'Economics', 'MICROECONOMICS\r\n\r\n1. DEMAND\r\nLaw: P↑ → Qd↓\r\nCurve: downward sloping\r\nShifters: Income, Tastes, Prices of related\r\nElasticity: %ΔQ/%ΔP\r\n\r\n2. SUPPLY\r\nLaw: P↑ → Qs↑\r\nCurve: upward sloping\r\nShifters: Input costs, Technology, Taxes\r\n\r\n3. EQUILIBRIUM\r\nQd = Qs\r\nSurplus, Shortage\r\nPrice mechanism\r\n\r\n4. ELASTICITY\r\nElastic: |E| > 1\r\nInelastic: |E| < 1\r\nUnitary: |E| = 1\r\n\r\n5. CONSUMER THEORY\r\nUtility\r\nMarginal utility\r\nIndifference curves\r\nBudget constraint\r\nConsumer surplus\r\n\r\n6. PRODUCTION\r\nFixed vs Variable costs\r\nShort run vs Long run\r\nLaw of diminishing returns\r\nEconomies of scale\r\n\r\n7. MARKET STRUCTURES\r\nPerfect Competition: many, identical\r\nMonopoly: one seller\r\nOligopoly: few sellers\r\nMonopolistic: differentiated\r\n\r\n8. EXTERNALITIES\r\nPositive: education\r\nNegative: pollution\r\nPigouvian taxes\r\nCoase theorem', 'note_275_microeconomics.pdf', 'Micro.pdf', 1922, 'application/pdf', 234, '2026-10-08 11:16:42'),
(276, 1, 8, 'Macroeconomics', 'GDP, inflation, policy', 'Economics', 'MACROECONOMICS\r\n\r\n1. GDP\r\nY = C + I + G + (X - M)\r\nNominal vs Real\r\nPer capita\r\n\r\n2. INFLATION\r\nCPI, PPI\r\nDemand-pull, Cost-push\r\nWinners/Losers\r\nHyperinflation\r\n\r\n3. UNEMPLOYMENT\r\nTypes: Frictional, Structural, Cyclical\r\nNatural rate\r\nOkun\'s law\r\nPhillips curve\r\n\r\n4. BUSINESS CYCLE\r\nExpansion, Peak, Recession, Trough\r\n\r\n5. FISCAL POLICY\r\nGovernment spending\r\nTaxation\r\nExpansionary: increase G, cut T\r\nContractionary: opposite\r\nMultiplier effect\r\nDeficit, Debt\r\n\r\n6. MONETARY POLICY\r\nCentral bank (RBI, Fed)\r\nInterest rates\r\nOpen market operations\r\nReserve requirements\r\nExpansionary vs Contractionary\r\n\r\n7. MONEY\r\nFunctions: medium, unit, store\r\nM1, M2, M3\r\nMoney multiplier\r\nQuantity theory: MV = PY\r\n\r\n8. INTERNATIONAL\r\nTrade, Comparative advantage\r\nExchange rates\r\nBalance of payments\r\nIMF, World Bank, WTO', 'note_276_macroeconomics.pdf', 'Macro.pdf', 1945, 'application/pdf', 267, '2026-10-08 11:16:42'),
(277, 1, 8, 'Indian Economy', 'India economic overview', 'Economics', 'INDIAN ECONOMY\r\n\r\n1. SECTORS\r\nPrimary: Agriculture\r\nSecondary: Manufacturing\r\nTertiary: Services\r\nQuaternary: Knowledge\r\n\r\n2. POST-INDEPENDENCE\r\nMixed economy\r\nFive Year Plans (1951-2017)\r\nGreen Revolution\r\nWhite Revolution\r\nLicense Raj\r\n\r\n3. 1991 REFORMS\r\nLPG: Liberalization, Privatization, Globalization\r\nManmohan Singh\r\nEnd of License Raj\r\nFDI opened\r\n\r\n4. AGRICULTURE\r\n60% employment\r\nMonsoon dependent\r\nMSP\r\nFCI, PDS\r\nGreen Revolution crops\r\n\r\n5. INDUSTRY\r\nMSMEs\r\nMake in India\r\nPLI schemes\r\nStartup India\r\n\r\n6. SERVICES\r\nIT/BPO leader\r\nBangalore, Hyderabad\r\nBanking, Insurance\r\nTourism\r\n\r\n7. DEMOGRAPHICS\r\n1.4 billion people\r\nMedian age: 28\r\nDemographic dividend\r\nUrbanization\r\n\r\n8. CHALLENGES\r\nUnemployment\r\nInequality\r\nInflation\r\nInfrastructure\r\nCurrent account deficit', 'note_277_indian_economy.pdf', 'IndianEconomy.pdf', 1919, 'application/pdf', 178, '2026-10-08 11:16:42'),
(278, 1, 8, 'Business Studies', 'Management, marketing, finance', 'Economics', 'BUSINESS STUDIES\r\n\r\n1. MANAGEMENT\r\nFunctions: Planning, Organizing, Staffing, Directing, Controlling\r\nLevels: Top, Middle, Supervisory\r\nPrinciples (Fayol): Division of work, Authority, Discipline\r\n\r\n2. MARKETING\r\n4Ps: Product, Price, Place, Promotion\r\nSTP: Segmentation, Targeting, Positioning\r\nMarketing mix\r\nBranding, Packaging\r\nDigital marketing, SEO, Social media\r\n\r\n3. FINANCE\r\nSources: Equity, Debt\r\nFinancial statements: Balance sheet, P&L, Cash flow\r\nRatio analysis\r\nWorking capital\r\nCapital budgeting\r\nBreak-even analysis\r\n\r\n4. HUMAN RESOURCES\r\nRecruitment, Selection\r\nTraining, Development\r\nPerformance appraisal\r\nCompensation\r\nLabor relations\r\n\r\n5. OPERATIONS\r\nProduction planning\r\nQuality control (TQM, Six Sigma)\r\nInventory (JIT)\r\nSupply chain\r\n\r\n6. ENTREPRENEURSHIP\r\nStartup stages\r\nBusiness plan\r\nFunding: Bootstrap, VC, Angel\r\nRisk and reward\r\nInnovation\r\n\r\n7. BUSINESS ETHICS\r\nCSR\r\nSustainability\r\nCorporate governance\r\nStakeholder theory', 'note_278_business_studies.pdf', 'Business.pdf', 2088, 'application/pdf', 145, '2026-10-08 11:16:42'),
(279, 1, 9, 'Physical Geography', 'Earth, climate, landforms', 'Geography', 'PHYSICAL GEOGRAPHY\r\n\r\n1. EARTH STRUCTURE\r\nCrust (5-70 km)\r\nMantle (2,900 km)\r\nOuter core (liquid)\r\nInner core (solid)\r\nPlates, Plate tectonics\r\n\r\n2. LANDFORMS\r\nMountains: Fold, Block, Volcanic\r\nPlateaus, Plains\r\nValleys: V-shaped, U-shaped (glaciers)\r\nCoastal: Cliffs, Beaches, Deltas\r\n\r\n3. CLIMATE\r\nKoppen classification\r\nTropical, Dry, Temperate, Continental, Polar\r\nFactors: Latitude, Altitude, Distance from sea\r\nMonsoon\r\n\r\n4. ATMOSPHERE\r\nTroposphere (weather)\r\nStratosphere (ozone)\r\nMesosphere\r\nThermosphere\r\nExosphere\r\n\r\n5. OCEANS\r\nPacific (largest), Atlantic, Indian, Arctic, Southern\r\nCurrents, Tides\r\nOcean floor: shelf, slope, trench\r\n\r\n6. RIVERS\r\nErosion, Transportation, Deposition\r\nMeanders, Oxbow lakes\r\nDeltas, Flood plains\r\n\r\n7. GLACIERS\r\nFormation\r\nErosion: Cirque, Arête, Horn\r\nDeposition: Moraine, Drumlin\r\nIce ages', 'note_279_physical_geography.pdf', 'PhysicalGeo.pdf', 1966, 'application/pdf', 189, '2026-10-08 11:16:42'),
(280, 1, 9, 'Human Geography', 'Population, culture, urbanization', 'Geography', 'HUMAN GEOGRAPHY\r\n\r\n1. POPULATION\r\nDistribution: 90% in Northern Hemisphere\r\nDensity: persons/km²\r\nGrowth: Births - Deaths + Migration\r\nDemographic transition:\r\n  Stage 1: High birth, high death\r\n  Stage 2: High birth, low death\r\n  Stage 3: Low birth, low death\r\n  Stage 4: Declining pop\r\n\r\n2. MIGRATION\r\nPush factors: War, poverty, disaster\r\nPull factors: Jobs, education, freedom\r\nTypes: Internal, International\r\nRefugees, IDPs\r\n\r\n3. CULTURE\r\nLanguage families\r\nReligions\r\nEthnic groups\r\nCultural regions\r\n\r\n4. ECONOMIC ACTIVITIES\r\nPrimary: Agriculture, mining\r\nSecondary: Manufacturing\r\nTertiary: Services\r\nQuaternary: Knowledge\r\n\r\n5. URBANIZATION\r\nRural → Urban migration\r\nMegacities: Tokyo, Delhi, Shanghai\r\nUrban problems: Slums, pollution, traffic\r\nSmart cities\r\n\r\n6. INDUSTRY LOCATION\r\nWeber\'s model\r\nRaw materials, Market, Transport\r\nSpecial Economic Zones\r\n\r\n7. POLITICAL\r\nNation-states\r\nBoundaries\r\nGeopolitics\r\nUN, Regional blocs', 'note_280_human_geography.pdf', 'HumanGeo.pdf', 2056, 'application/pdf', 156, '2026-10-08 11:16:42'),
(281, 1, 9, 'Indian Geography', 'India physical and human', 'Geography', 'INDIAN GEOGRAPHY\r\n\r\n1. LOCATION\r\n8°4\' to 37°6\' N\r\n68°7\' to 97°25\' E\r\n3.28 million km²\r\n7th largest country\r\n\r\n2. PHYSICAL DIVISIONS\r\nHimalayas\r\nIndo-Gangetic Plain\r\nPeninsular Plateau\r\nCoastal Plains\r\nIslands: Andaman, Lakshadweep\r\n\r\n3. RIVERS\r\nHimalayan: Indus, Ganga, Brahmaputra\r\nPeninsular: Godavari, Krishna, Kaveri\r\nPerennial vs seasonal\r\n\r\n4. CLIMATE\r\nTropical monsoon\r\nSeasons: Winter, Summer, Monsoon, Post-monsoon\r\nRainfall: 100-300 cm\r\nBay of Bengal, Arabian Sea branches\r\n\r\n5. SOILS\r\nAlluvial (fertile)\r\nBlack (regur, cotton)\r\nRed, Laterite\r\nDesert, Mountain\r\n\r\n6. AGRICULTURE\r\nKharif (monsoon): Rice, maize\r\nRabi (winter): Wheat, gram\r\nZaid (summer): Vegetables\r\nCash crops: Cotton, sugarcane, tea\r\n\r\n7. MINERALS\r\nCoal (Jharkhand, Odisha)\r\nIron (Odisha, Chhattisgarh)\r\nBauxite, Manganese\r\nPetroleum (Mumbai High)\r\n\r\n8. INDUSTRY\r\nTextiles, Steel, IT\r\nIndustrial regions: Mumbai-Pune, Bengaluru\r\nSEZs, Industrial corridors', 'note_281_indian_geography.pdf', 'IndianGeo.pdf', 2079, 'application/pdf', 234, '2026-10-08 11:16:42'),
(282, 1, 10, 'Study Skills', 'How to study effectively', 'General', 'STUDY SKILLS\r\n\r\n1. TIME MANAGEMENT\r\nPomodoro: 25 min + 5 min break\r\nEisenhower Matrix: Urgent vs Important\r\nTo-do lists, Planner\r\nAvoid multitasking\r\n\r\n2. ACTIVE LEARNING\r\nFeynman Technique:\r\n  1. Pick a concept\r\n  2. Explain to a child\r\n  3. Identify gaps\r\n  4. Simplify\r\n\r\nCornell Notes:\r\n  Column for cues, notes, summary\r\n\r\nMind maps, Flashcards\r\n\r\n3. MEMORY\r\nSpaced repetition\r\nMnemonic devices\r\nChunking\r\nSleep (crucial for consolidation)\r\n\r\n4. FOCUS\r\nRemove distractions\r\nPhone away\r\nStudy environment\r\nDeep work blocks\r\n\r\n5. EXAM PREP\r\nStart early\r\nPractice papers\r\nReview past mistakes\r\nTeach others\r\nSimulate exam conditions\r\n\r\n6. WELLBEING\r\nSleep 7-8 hours\r\nExercise\r\nHydration\r\nNutrition\r\nBreaks\r\nSocial connection', 'note_282_study_skills.pdf', 'StudySkills.pdf', 1834, 'application/pdf', 345, '2026-10-08 11:16:42'),
(283, 1, 10, 'Critical Thinking', 'Logic, arguments, fallacies', 'General', 'CRITICAL THINKING\r\n\r\n1. LOGIC\r\nPremises → Conclusion\r\nDeductive: general → specific\r\nInductive: specific → general\r\nValidity vs Soundness\r\n\r\n2. FALLACIES\r\nAd hominem: attack person\r\nStraw man: misrepresent\r\nFalse dilemma: only 2 options\r\nSlippery slope: chain of events\r\nAppeal to authority\r\nBandwagon\r\nCircular reasoning\r\nHasty generalization\r\n\r\n3. ARGUMENTS\r\nClaim, Evidence, Reasoning\r\nCounter-arguments\r\nRebuttals\r\n\r\n4. EVIDENCE\r\nPrimary vs Secondary\r\nReliable sources\r\nPeer-reviewed\r\nBias, Sample size\r\n\r\n5. COGNITIVE BIASES\r\nConfirmation bias\r\nAnchoring\r\nAvailability heuristic\r\nHindsight bias\r\nDunning-Kruger\r\n\r\n6. DECISION MAKING\r\nPros/Cons\r\nCost-benefit\r\nExpected value\r\nSunk cost fallacy\r\nOpportunity cost\r\n\r\n7. PROBLEM SOLVING\r\nDefine problem\r\nGenerate options\r\nEvaluate\r\nChoose\r\nImplement\r\nReview', 'note_283_critical_thinking.pdf', 'Critical.pdf', 1946, 'application/pdf', 234, '2026-10-08 11:16:42'),
(284, 1, 10, 'Time Management', 'Productivity strategies', 'General', 'TIME MANAGEMENT\r\n\r\n1. PRINCIPLES\r\nParkinson\'s Law: work expands to fill time\r\nPareto: 80/20 rule\r\nEisenhower Matrix:\r\n  Important + Urgent: Do now\r\n  Important + Not: Schedule\r\n  Not + Urgent: Delegate\r\n  Not + Not: Delete\r\n\r\n2. TECHNIQUES\r\nPomodoro (25+5)\r\nTime blocking\r\nGetting Things Done (GTD):\r\n  Capture, Clarify, Organize, Reflect, Engage\r\nEat the Frog (hardest first)\r\n\r\n3. TOOLS\r\nCalendar (Google, Outlook)\r\nTask managers (Todoist, Things)\r\nNotes (Notion, Obsidian)\r\nFocus apps (Forest, Cold Turkey)\r\n\r\n4. HABITS\r\nMorning routine\r\nWeekly review\r\nBatch similar tasks\r\nLearn to say no\r\nDelegate\r\n\r\n5. ENERGY\r\nUltradian rhythms (90 min)\r\nRest, breaks\r\nNutrition, hydration\r\nExercise\r\nSleep\r\n\r\n6. GOALS\r\nSMART: Specific, Measurable, Achievable,\r\nRelevant, Time-bound\r\nShort, medium, long term\r\nReview, adjust\r\n\r\n7. PROCRASTINATION\r\n2-minute rule\r\nBreak tasks\r\nAccountability\r\nRewards\r\nRemove friction', 'note_284_time_management.pdf', 'TimeMgmt.pdf', 2045, 'application/pdf', 198, '2026-10-08 11:16:42'),
(285, 1, 1, 'Automated Test Upload Note', 'A test note description uploaded by test', 'Mathematics', NULL, 'b72c7d6d39fea053ead63f69d27a1b33.pdf', 'test_note.pdf', 47, 'application/pdf', 0, '2026-10-08 11:36:04');

